// Üretilen dosya: tool/ozgun/uret.py. Fizik ve Astronomi · Basit makineler, tork, kütle merkezi ve statik denge sistemleri (kaldıraç, makara, palanga, eğik düzlem, vida, çıkrık, dişli ve kasnaklar) (orta).
const ozPhysics15Orta = <(String, String, List<String>, String)>[
  ('Bir musluk başlığını açmak için karşılıklı iki ucuna eşit büyüklükte, birbirine paralel ve zıt yönlü iki kuvvet uygulandığında oluşan özel kuvvet çiftine mekanikte ne ad verilir?', 'Net kuvveti sıfır olup saf dönme üreten kuvvet çifti', ['Bileşkesi maksimum öteleme ivmesi yaratan eş yönlü çift', 'Menteşe tepkisini sonsuza çıkaran merkezcil kuvvet sistemi', 'Sadece şekil değişikliği oluşturan esnek gerilme çifti'], 'Eşit büyüklükte ve zıt yönlü paralel iki kuvvetin bileşkesi sıfırdır ancak aynı yönde tork ürettikleri için kuvvet çifti oluştururlar.'),
  ('İş birimi olan Joule (N·m) ile tork birimi olan Newton·metre boyutsal olarak aynı görünmesine rağmen torku Joule ile ifade etmememizin temel fiziksel nedeni nedir?', 'Torkun vektörel çarpımdan doğan yönlü bir nicelik olması', ['İşin yalnızca sürtünmesiz ortamlarda tanımlanabilmesi', 'Tork hesabında zaman değişkeninin paydada yer alması', 'Enerjinin korunumu yasasının dönen cisimlerde geçersiz kalması'], 'İş kuvvet ile yer değiştirmenin skaler çarpımıyken, tork konum vektörü ile kuvvetin vektörel çarpımıdır; karışıklığı önlemek için Joule kullanılmaz.'),
  ('Bir duvar saatinin yelkovanı 12 rakamından 3 rakamına doğru ilerlerken yelkovanın kendi ağırlığının saat göbeğine göre oluşturduğu torkun büyüklüğü nasıl değişir?', 'Sıfırdan başlayarak sürekli artar ve 3 konumunda maksimuma ulaşır', ['Maksimum değerden başlayarak azalır ve 3 konumunda sıfırlanır', 'Hareket süresince ağırlık değişmediği için hep sabit kalır', 'Önce artıp 2 rakamı hizasında maksimum olduktan sonra azalır'], '12 konumunda ağırlık vektörü dönme noktasından geçer (tork sıfır). Yatay 3 konumuna geldikçe dik uzaklık sinθ ile artarak maksimum olur.'),
  ('Ağırlığı 40 N olan 6 eşit bölmeli türdeş bir kalas, sol ucundan 2 bölme içerideki bir desteğin üzerine yatay olarak yerleştirilmiştir. Kalasın sağ ucuna 10 N\'luk bir kutu konulduğunda yatay dengenin bozulmaması için sol uca kaç N\'luk düşey kuvvet uygulanmalıdır?', 'Sol uca aşağı yönlü 40 N uygulanmalıdır', ['Sol uca aşağı yönlü 20 N uygulanmalıdır', 'Sol uca yukarı yönlü 35 N uygulanmalıdır', 'Sol uca aşağı yönlü 50 N uygulanmalıdır'], 'Destek 2. bölmededir. Kalas ağırlığı (40 N) 3. bölmede (desteğe 1 br sağda), kutu (10 N) 6. bölmede (desteğe 4 br sağda). Sol uç (desteğe 2 br solda): F·2 = 40·1 + 10·4 = 80 => F = 40 N.'),
  ('Kenar uzunluğu a olan kare biçimindeki bir levhanın merkezi olan O noktası sabitlenmiştir. Karenin dört kenarı boyunca aynı dolanım yönünde her kenara teğet olarak 15 N büyüklüğünde dört özdeş kuvvet etki ederse O noktasına göre bileşke tork ne olur?', '30·a büyüklüğünde aynı dolanım yönünde olur', ['60·a büyüklüğünde aynı dolanım yönünde olur', 'Kuvvetler birbirini sıfırladığı için toplam tork sıfırdır', '15·a büyüklüğünde zıt dolanım yönünde olur'], 'Her kuvvetin merkeze dik uzaklığı a/2 kadardır. Dört kuvvet de aynı yönde döndürdüğünden toplam tork = 4 · 15 · (a/2) = 30·a bulunur.'),
  ('Yarıçapları sırasıyla r ve 3r olan eş merkezli ve birbirine perçinlenmiş iki disk merkezlerinden geçen mil etrafında dönebilmektedir. İç diske saat yönünde 45 N, dış diske saatin tersi yönde 20 N teğet kuvvet uygulanırsa net tork hangi yönde ve kaç F·r olur? (F = 5 N alınız)', 'Saatin tersi yönde 3 F·r büyüklüğünde', ['Saat yönünde 9 F·r büyüklüğünde', 'Saatin tersi yönde 12 F·r büyüklüğünde', 'Saat yönünde 5 F·r büyüklüğünde'], 'Saat yönü: 45·r = 9 F·r. Saatin tersi: 20·3r = 60·r = 12 F·r. Fark saatin tersi yönde 60r - 45r = 15r = 3 F·r olur.'),
  ('Sürtünmesiz yatay masa üzerindeki 1 m uzunluğundaki çubuğun sol ucuna +y yönünde 12 N, orta noktasına -y yönünde 30 N ve sağ ucuna +y yönünde 18 N kuvvet etki ediyor. Bu çubuğun hareket durumu için ne söylenebilir?', 'Öteleme yapmaz ancak saat yönünün tersine döner', ['Hem öteleme hem dönme dengesinde hareketsiz kalır', 'Saat yönünde dönerken +y yönünde ivmelenerek ötelenir', 'Dönmeden yalnızca -y yönünde sabit ivmeyle kayar'], 'Net kuvvet = 12 - 30 + 18 = 0 (öteleme ivmesi yok). Sol uca göre tork = -30·0,5 + 18·1 = +3 N·m ≠ 0 olduğundan saatin tersi yönde döner.'),
  ('İnsan ön kolu dirsek eklemi etrafında bükülürken biseps kası dirsekten 4 cm ileriye bağlanarak yukarı çekmekte, avuç içinde dirsekten 32 cm uzakta ise 25 N ağırlığında bir gülle tutulmaktadır. Ön kol ağırlığı ihmal edilirse yatay denge için biseps kasının gerilmesi kaç N olmalıdır?', '200 N büyüklüğünde kas kuvveti', ['160 N büyüklüğünde kas kuvveti', '100 N büyüklüğünde kas kuvveti', '320 N büyüklüğünde kas kuvveti'], 'Dirsek eklemine göre tork dengesi: F_kas · 4 = 25 · 32 => 4 · F_kas = 800 => F_kas = 200 N olarak bulunur.'),
  ('90° bükülmüş L biçimindeki ağırlıksız sert telin kısa kolu 30 cm, uzun kolu 40 cm olup bükülme köşesinden menteşelenmiştir. Kısa kol yatay, uzun kol düşey aşağı sarkarken uzun kolun alt ucuna yatay sağa 18 N uygulanıyor. Sistemi dengelemek için kısa kolun ucuna düşey kaç N uygulanmalıdır?', '24 N büyüklüğünde düşey kuvvet', ['13,5 N büyüklüğünde düşey kuvvet', '18 N büyüklüğünde düşey kuvvet', '30 N büyüklüğünde düşey kuvvet'], 'Köşe menteşesine göre tork eşitliği yazılır: F · 0,30 = 18 · 0,40 => 0,3 F = 7,2 => F = 24 N elde edilir.'),
  ('Kapı kollarının menteşeye mümkün olduğunca uzak kenara monte edilmesi ile aşağıdaki günlük yaşam araçlarından hangisinin tasarım ilkesi birebir aynı fiziksel nedene dayanır?', 'Bahçe budama makaslarında tutma saplarının uzun yapılması', ['Cımbız uçlarının ince ve tutma yerine uzak tasarlanması', 'Buz hokeyi sopasının alt vuruş kısmının uzun tutulması', 'Olta kamışının uç kısmının esnek ve oldukça uzun olması'], 'Budama makasında uzun saplar, tıpkı kapı kolunun menteşeden uzak olması gibi kuvvet kolunu büyüterek küçük kuvvetle büyük tork üretir.'),
  ('Uzunluğu 2,4 m ve ağırlığı 60 N olan düzgün türdeş bir kalasın sol ucu menteşelidir. Sağ ucuna bağlanan düşey bir yay kalası yatay konumda dengede tuttuğuna göre, yay sabiti k = 500 N/m olan bu yay kaç cm uzamıştır?', 'Yay 6 cm kadar uzamıştır', ['Yay 12 cm kadar uzamıştır', 'Yay 3 cm kadar uzamıştır', 'Yay 15 cm kadar uzamıştır'], 'Menteşeye göre tork: F_yay · 2,4 = 60 · 1,2 => F_yay = 30 N. Hooke yasasından 30 = 500 · x => x = 0,06 m = 6 cm bulunur.'),
  ('Ağırlığı 50 N ve taban kenarı 40 cm, yüksekliği 100 cm olan dikdörtgenler prizması şeklindeki türdeş mermer blok yatay zeminde durmaktadır. Bloğu kaydırmadan alt sağ köşesi etrafında devirmeye başlamak için sol üst köşeye yatay sağa en az kaç N kuvvet uygulanmalıdır?', 'En az 10 N yatay kuvvet yeterlidir', ['En az 20 N yatay kuvvet yeterlidir', 'En az 25 N yatay kuvvet yeterlidir', 'En az 50 N yatay kuvvet yeterlidir'], 'Sağ alt köşeye göre ağırlığın dik uzaklığı 20 cm, yatay kuvvetin dik uzaklığı 100 cm\'dir: F · 100 = 50 · 20 => F = 10 N bulunur.'),
  ('Bir somun anahtarına dik uygulanan F kuvveti somunu sökemeyince usta, anahtar uzunluğunu 1,5 katına çıkarıp uyguladığı dik kuvveti de %20 artırıyor. Yeni durumda oluşan tork ilk duruma göre yüzde kaç artmıştır?', 'İlk duruma göre %80 artmıştır', ['İlk duruma göre %70 artmıştır', 'İlk duruma göre %50 artmıştır', 'İlk duruma göre %120 artmıştır'], 'İlk tork τ₁ = F·d iken yeni tork τ₂ = (1,2 F)·(1,5 d) = 1,80 F·d olur; bu da %80 artış demektir.'),
  ('Ağırlığı önemsenmeyen eşit bölmeli bir çubuk, sol uçtaki K noktası etrafında serbestçe dönebilmektedir. Çubuğun 3. bölmesine 20 N\'luk yük asılmış, 6. bölmesinden ise çubukla 37° açı yapan bir iple yukarı doğru bağlanmıştır. Yatay denge için ipteki gerilme kaç N olmalıdır? (sin37° = 0,6)', 'İpteki gerilme 50/3 N olmalıdır', ['İpteki gerilme 25 N olmalıdır', 'İpteki gerilme 10 N olmalıdır', 'İpteki gerilme 40/3 N olmalıdır'], 'K noktasına göre tork: T · sin37° · 6 = 20 · 3 => T · 0,6 · 6 = 60 => 3,6 T = 60 => T = 600/36 = 50/3 N bulunur.'),
  ('Kütlesi 8 kg olan homojen bir küre, eğim açısı 30° olan pürüzsüz eğik düzlem ile eğik düzleme dik yerleştirilmiş bir takoz arasında dengededir. Küre merkezine göre takozun ve eğik düzlemin tepki kuvvetlerinin toplam torku kaç N·m\'dir? (g = 10 m/s², yarıçap = 25 cm)', 'Kuvvetlerin uzantıları merkezden geçtiği için sıfırdır', ['10 N·m büyüklüğünde saat yönündedir', '20 N·m büyüklüğünde saatin tersi yöndedir', '5√3 N·m büyüklüğünde sayfa içine doğrudur'], 'Pürüzsüz yüzeylerin küreye uyguladığı normal tepki kuvvetleri küre yüzeyine diktir ve uzantıları küre merkezinden geçer; bu nedenle merkeze göre torkları sıfırdır.'),
  ('Birim kareli düzlemde O noktasına göre F₁ kuvvetinin torku +τ iken F₂ kuvvetinin torku -3τ olarak ölçülüyor. Yalnızca F₂ kuvvetinin yönü ters çevrilip büyüklüğü yarıya indirilirse yeni bileşke tork kaç τ olur?', '+5τ/2 değerine eşit olur', ['-τ/2 değerine eşit olur', '+2τ değerine eşit olur', '-2τ değerine eşit olur'], 'F₂ ters çevrilip yarıya inerse torku da işaret değiştirip yarıya iner ve +1,5τ olur. Toplam tork = +τ + 1,5τ = +2,5τ (+5τ/2) bulunur.'),
  ('Eşit bölmeli 8 birimli türdeş bir çubuğun ağırlığı 24 N\'dur. Çubuk soldan 2. bölme noktası üzerine konulan destek üzerinde dururken, sağ uca bağlı ve tavana tutturulmuş düşey bir ip çubuğu yatay dengede tutuyor. Desteğin çubuğa uyguladığı tepki kuvveti kaç N\'dur?', '16 N büyüklüğünde yukarı yönlüdür', ['12 N büyüklüğünde yukarı yönlüdür', '8 N büyüklüğünde yukarı yönlüdür', '20 N büyüklüğünde yukarı yönlüdür'], 'Ağırlık 4. bölmede, ip 8. bölmededir. İpe göre tork alınırsa: N_destek · (8 - 2) = 24 · (8 - 4) => 6 N_destek = 96 => N_destek = 16 N bulunur.'),
  ('Uzunluğu 3 m olan homojen olmayan bir kalas sol ucundan yerden hafifçe kaldırılmak istendiğinde 40 N, sağ ucundan hafifçe kaldırılmak istendiğinde ise 80 N düşey kuvvet gerekiyor. Buna göre kalasın ağırlığı ve kütle merkezinin sol uca uzaklığı nedir?', 'Ağırlığı 120 N olup sol uçtan 2 m uzaktadır', ['Ağırlığı 120 N olup sol uçtan 1 m uzaktadır', 'Ağırlığı 60 N olup sol uçtan 2 m uzaktadır', 'Ağırlığı 80 N olup sol uçtan 1,5 m uzaktadır'], 'Sağ uca göre tork: 40·3 = G·(3 - x); sol uca göre tork: 80·3 = G·x. Taraf tarafa toplanırsa 360 = 3G => G = 120 N ve 120·x = 240 => x = 2 m bulunur.'),
  ('Kenar uzunluğu 50 cm olan küp biçimindeki 160 N ağırlıklı türdeş sandık, eğim açısı 37° olan pürüzlü bir rampa üzerinde kaymadan durmaktadır. Sandığın alt köşesi etrafında devrilmeye karşı dengeleyici net tork ile devirici tork ilişkisi incelendiğinde, devrilmemesi aşağıdaki hangi geometrik koşulla doğrulanır? (tan37° = 0,75)', 'Ağırlık vektörü uzantısının taban yüzeyi içinden geçmesiyle', ['Sürtünme kuvvetinin sandık ağırlığından daha büyük olmasıyla', 'Normal tepki kuvvetinin tam küp merkezinden geçmesiyle', 'Rampa uzunluğunun küp kenarının dört katını aşmasıyla'], 'tan37° = 0,75 < 1 olduğundan küpün merkezinden inen düşey ağırlık doğrusu tabanın içinden geçer ve alt köşeye göre ters yönlü (dengeleyici) tork üretir.'),
  ('Sabit O noktası etrafında dönebilen çubuğa etki eden F kuvvetinin O noktasına göre tork vektörü τ = r × F ile tanımlanır. Yalnızca konum vektörü r ile kuvvet vektörü F kendi aralarında yer değiştirilseydi (F × r alınsaydı) sonuç nasıl etkilenirdi?', 'Büyüklüğü aynı kalır fakat vektörün yönü tam tersine dönerdi', ['Hem büyüklüğü hem de yönü hiçbir değişikliğe uğramazdı', 'Büyüklüğü sıfırlanarak skaler bir enerji niceliğine dönüşürdü', 'Yönü değişmez ancak büyüklüğü sinüs yerine kosinüsle çarpılırdı'], 'Vektörel çarpımda değişme özelliği yoktur, ters simetriktir: F × r = -(r × F). Dolayısıyla büyüklük korunur ama yön zıt olur.'),
  ('Uzunluğu 120 cm olan ağırlıksız yatay bir çubuk, sol ucundan 40 cm içerideki K desteği ve sağ ucundan 20 cm içerideki L desteği üzerine konulmuştur. Sol uca 50 N\'luk yük asıldığında çubuğun K desteği etrafında devrilmemesi için sağ uca en az kaç N yük asılmalıdır?', 'Sağ uca en az 25 N yük asılmalıdır', ['Sağ uca en az 50 N yük asılmalıdır', 'Sağ uca en az 40 N yük asılmalıdır', 'Sağ uca en az 20 N yük asılmalıdır'], 'K desteği 40. cm\'de olduğundan sol uca uzaklığı 40 cm, sağ uca (120. cm) uzaklığı ise 80 cm\'dir: 50 · 40 = G · 80 => G = 25 N bulunur.'),
  ('O merkezli yarım daire biçimindeki r = 60 cm yarıçaplı tel çerçeve, çapının sol ucu olan K noktasından menteşelenmiştir. Çap doğrusu yatayken yayın tepe noktası olan M\'ye yatay sağa doğru 25 N\'luk kuvvet uygulanıyor. K noktasına göre oluşan tork kaç N·m\'dir?', 'Saat yönünde 15 N·m tork oluşur', ['Saat yönünde 30 N·m tork oluşur', 'Saatin tersi yönde 15 N·m tork oluşur', 'Saat yönünde 22,5 N·m tork oluşur'], 'Tepe noktası M\'den geçen yatay doğrunun K menteşesine dik (düşey) uzaklığı yarıçap r = 0,6 m kadardır. Tork = 25 · 0,6 = 15 N·m (saat yönünde).'),
  ('Düzgün kesitli ve kendi içinde türdeş iki ayrı metal çubuk uç uca kaynak yapılarak tek bir doğrusal çubuk elde ediliyor. Birinci parçanın boyu 2 m ve ağırlığı 20 N, ikinci parçanın boyu 2 m ve ağırlığı 60 N\'dur. Birleşik çubuğu hafif parçanın serbest ucundan menteşeleyip yatay tutmak için ağır parçanın serbest ucundan düşey yukarı kaç N kuvvet uygulanmalıdır?', '50 N büyüklüğünde düşey kuvvet', ['40 N büyüklüğünde düşey kuvvet', '45 N büyüklüğünde düşey kuvvet', '35 N büyüklüğünde düşey kuvvet'], 'Toplam boy 4 m\'dir. Sol uca (menteşe) göre 20 N\'un kolu 1 m, 60 N\'un kolu 3 m\'dir: F · 4 = 20 · 1 + 60 · 3 = 200 => F = 50 N bulunur.'),
  ('Eşit kare bölmeli düzlemde O köşesinden geçen dik eksen etrafında dönebilen 3×3 karelik levhaya, sağ üst köşesinden sola doğru yatay 10 N ve sağ alt köşesinden yukarı doğru düşey 15 N kuvvet uygulanıyor (O noktası sol alt köşedir, her kare kenarı 0,2 m). O noktasına göre bileşke tork nedir?', 'Saatin tersi yönde 15 N·m büyüklüğündedir', ['Saatin tersi yönde 3 N·m büyüklüğündedir', 'Saat yönünde 9 N·m büyüklüğündedir', 'Saatin tersi yönde 6 N·m büyüklüğündedir'], 'Levha kenarı 3 · 0,2 = 0,6 m\'dir. Sağ üstten sola 10 N saatin tersi yönde 10·0,6 = 6 N·m; sağ alttan yukarı 15 N da saatin tersi yönde 15·0,6 = 9 N·m üretir. Toplam = 15 N·m.'),
  ('Ağırlığı G olan düzgün türdeş bir çubuk, sol ucundan duvara menteşelenmiş ve orta noktasından çubuğa dik bağlanan bir iple dengelenmiştir. İp sökülüp çubuğun sağ ucuna yine çubuğa dik olacak biçimde bağlanırsa, aynı denge konumunda ipteki gerilme ve ipin menteşeye göre torku nasıl değişir?', 'İp gerilmesi yarıya inerken menteşeye göre torku değişmez', ['İp gerilmesi iki katına çıkarken menteşeye göre torku da artar', 'İp gerilmesi yarıya inerken menteşeye göre torku da yarıya iner', 'Hem ip gerilmesi hem de menteşeye göre oluşturduğu tork sabit kalır'], 'Ağırlığın menteşeye göre torku değişmediğinden ipin dengeleyici torku sabit kalır; dik uzaklık iki katına çıktığı için ip gerilmesi yarıya iner.'),
  ('Bir bisikletin arka tekerlek göbeğine takılı 5 cm yarıçaplı ruble dişlisine zincir tarafından 180 N çekme kuvveti uygulanmaktadır. Tekerleğin dış yarıçapı 30 cm olduğuna göre, tekerlek sabit hızla dönerken yolun lastiğe uyguladığı sürtünme kuvveti göbeğe göre kaç N·m zıt tork üretir?', '9 N·m büyüklüğünde zıt tork üretir', ['30 N·m büyüklüğünde zıt tork üretir', '54 N·m büyüklüğünde zıt tork üretir', '18 N·m büyüklüğünde zıt tork üretir'], 'Tekerlek sabit açısal hızla döndüğüne göre göbeğe göre net tork sıfırdır. Zincirin torku τ = 180 · 0,05 = 9 N·m olduğundan sürtünme de 9 N·m zıt tork üretir.'),
  ('O noktasından geçen eksen etrafında dönebilen eşit bölmeli ağırlıksız çubuğun 4. bölmesine 30 N büyüklüğünde düşey aşağı bir kuvvet uygulanıyor. Çubuk yatayla 37° açı yapacak biçimde eğik durduğuna göre bu kuvvetin O noktasına göre torku kaç bölme·N olur? (sin37° = 0,6; cos37° = 0,8)', '96 bölme·N büyüklüğündedir', ['72 bölme·N büyüklüğündedir', '120 bölme·N büyüklüğündedir', '64 bölme·N büyüklüğündedir'], 'Çubuk yatayla 37° açı yaptığından düşey kuvvetin O noktasına yatay (dik) uzaklığı 4 · cos37° = 3,2 bölmedir. Tork = 30 · 3,2 = 96 bölme·N olur.'),
  ('Bir geminin dümenini ya da eski tip su vanalarını çevirirken çemberin karşılıklı iki kenarından iki elle zıt yönlerde itme-çekme uygulanmasının mekanik üstünlüğü nedir?', 'Mil yatağında ek yanal yük oluşturmadan iki elin torklarını toplamak', ['Ellerin uyguladığı torkları birbirinden çıkararak mili yavaşlatmak', 'Vana milinin kütlesini sıfırlayarak sürtünmesiz öteleme sağlamak', 'Uygulanan kuvvetlerin bileşkesini iki katına çıkarıp mili bükmek'], 'Kuvvet çifti uygulandığında net öteleme kuvveti sıfırlandığı için mil yatağı kasılmaz, ancak her iki elin torku aynı yönde toplanır.'),
  ('Uzunluğu 2 m ve ağırlığı 50 N olan türdeş bir kalas yatay zeminde boylu boyunca yatmaktadır. Kalasın bir ucundan tutup öteki ucu yerden ayrılmadan yatayla 60° açı yapacak konuma getirilmiş halde tutmak için kaldırılan uca dik olarak kaç N kuvvet uygulanmalıdır? (sin60° = 0,87; cos60° = 0,5)', '12,5 N büyüklüğünde dik kuvvet', ['25,0 N büyüklüğünde dik kuvvet', '21,75 N büyüklüğünde dik kuvvet', '50,0 N büyüklüğünde dik kuvvet'], 'Yerdeki uca göre ağırlığın yatay kolu (L/2)·cos60° = 1 · 0,5 = 0,5 m\'dir. Kaldırılan uca çubuğa dik uygulanan kuvvetin kolu 2 m: F · 2 = 50 · 0,5 => F = 12,5 N.'),
  ('Sürtünmesiz yatay buz pisti üzerinde duran 80 cm çaplı türdeş bir diskin kuzey ucuna doğu yönünde 20 N, güney ucuna da doğu yönünde 20 N kuvvet aynı anda uygulanıyor. Diskin kütle merkezine göre toplam tork ve ivmelenme durumu nedir?', 'Kütle merkezine göre net tork sıfırdır; disk dönmeden doğuya ivmelenir', ['16 N·m net torkla saat yönünde dönerken olduğu yerde kalır', '32 N·m net torkla hem saat yönünde döner hem doğuya ivmelenir', 'Kuvvetler birbirini dengelediği için disk tamamen hareketsiz kalır'], 'Kuzey ucundaki doğu kuvveti saat yönünde 20·0,4 = 8 N·m, güney ucundaki doğu kuvveti saatin tersi yönde 20·0,4 = 8 N·m tork üretir; net tork sıfırdır ama net kuvvet doğuya 40 N\'dur.'),
  ('O noktasından geçen mil etrafında dönebilen 3r, 2r ve r yarıçaplı üç eş merkezli kasnağa sarılı iplerin uçlarına sırasıyla G₁, G₂ ve G₃ yükleri asılmıştır. G₁ ve G₃ kasnakları saat yönünde, G₂ ise saatin tersi yönde döndürmeye çalışmaktadır. Sistem dengede ve G₁ = 2G₃ olduğuna göre G₂ / G₃ oranı kaçtır?', 'Oran 7/2 değerine eşittir', ['Oran 5/2 değerine eşittir', 'Oran 3 değerine eşittir', 'Oran 4 değerine eşittir'], 'Denge şartından: G₁·3r + G₃·r = G₂·2r. G₁ yerine 2G₃ yazılırsa: (2G₃)·3r + G₃·r = 7 G₃·r = 2 G₂·r => G₂ / G₃ = 7/2 bulunur.'),
  ('Bir gitarın akort burgusunu çevirirken parmaklarla burgu kulakçıklarına uygulanan kuvvetin telin sarıldığı ince silindirik mile göre tork dengesini sağlaması ne anlama gelir?', 'Tel gerilmesinin mil yarıçapıyla çarpımının burgu sürtünme ve el torkuna eşitlenmesi', ['Teldeki ses frekansının burgu kütlesiyle doğru orantılı olarak sabitlenmesi', 'Gitar gövdesinin toplam ağırlığının burgu pimi tarafından taşınması', 'Tel uzunluğunun mil yarıçapına bölünmesiyle kuvvet kazancının sıfırlanması'], 'Telin ince mile uyguladığı çekme kuvveti küçük yarıçapta bir geri döndürme torku üretir; geniş kulakçık ve dişli sürtünmesi bu torku dengeler.'),
  ('Bir terzi makasıyla kalın kumaş keserken kumaşı makasın uç kısmına değil de vidalı birleşim yerine yakın iç ağız kısmına yerleştirmesinin tork bakımından açıklaması nedir?', 'Direnç kuvvetinin dönme pimine uzaklığını küçülterek kumaşa binen kesme kuvvetini büyütmek', ['Parmakların uyguladığı kuvvetin pime göre torkunu yarıya indirerek eli dinlendirmek', 'Makas bıçaklarının açısal yer değiştirmesini artırarak tek hamlede uzun kesim yapmak', 'Vida pimindeki sürtünme torkunu artırarak bıçakların kendiliğinden açılmasını sağlamak'], 'Kumaş pime yaklaştıkça yük kolu d_yük küçülür; elin ürettiği tork sabitken d_yük küçüldüğünde kumaşa aktarılan kesme kuvveti F_kesme büyür.'),
  ('Ağırlığı 90 N olan düzgün türdeş kare levha bir köşesinden tavana iple asılmış, komşu alt köşesinden ise yatay bir iple çekilerek karenin üst kenarı yatay olacak biçimde dengelenmiştir. Alt köşedeki yatay ipin gerilme kuvveti kaç N olur?', '45 N büyüklüğünde yatay gerilme', ['90 N büyüklüğünde yatay gerilme', '30 N büyüklüğünde yatay gerilme', '60 N büyüklüğünde yatay gerilme'], 'Üst kenar yataysa asılma köşesinin hemen altında komşu alt köşe vardır (düşey uzaklık a). Ağırlık merkezi yatayda a/2 uzaktadır: T · a = 90 · (a/2) => T = 45 N.'),
  ('Üzerinde 1\'den 10\'a kadar eşit aralıklı çentikler bulunan ağırlıksız bir terazi kolu 4. çentikten desteklenmiştir. 1. çentiğe 24 N, 2. çentiğe 16 N yük asıldığında kolun yatay dengede kalması için 9. çentiğe kaç N yük asılmalıdır?', '9. çentiğe 20,8 N yük asılmalıdır', ['9. çentiğe 18,4 N yük asılmalıdır', '9. çentiğe 24,0 N yük asılmalıdır', '9. çentiğe 16,0 N yük asılmalıdır'], 'Destek 4. çentiktedir. Sol tork = 24·(4 - 1) + 16·(4 - 2) = 72 + 32 = 104 br·N. Sağda 9. çentik desteğe 5 br uzakta: G · 5 = 104 => G = 20,8 N.'),
  ('Bir vantilatörün fişi çekildikten sonra pervanesinin bir süre daha dönüp yavaşlayarak durması sürecinde pervanenin dönme eksenine göre net tork ve açısal hız vektörlerinin yön ilişkisi nasıldır?', 'Net tork vektörü açısal hız vektörüyle zıt yöndedir', ['Net tork vektörü açısal hız vektörüyle aynı yöndedir', 'Net tork vektörü açısal hız vektörüne dik düzlemdedir', 'Fiş çekildiği anda net tork vektörü sıfır değerini alır'], 'Yavaşlayan dönme hareketinde hava direnci ve yatak sürtünmesinin oluşturduğu net tork, mevcut dönme (açısal hız) vektörüne zıt yönlüdür.'),
  ('Uzunluğu 80 cm ve ağırlığı 20 N olan türdeş bir çubuğun sol ucu O noktasından menteşelidir. Sağ ucuna asılı 15 N\'luk bir kütle varken çubuğu orta noktasından çubukla 30° açı yapan bir iple yukarı doğru tutarak yatay denge sağlanıyor. İpteki gerilme kaç N\'dur? (sin30° = 0,5)', '100 N büyüklüğünde ip gerilmesi', ['50 N büyüklüğünde ip gerilmesi', '70 N büyüklüğünde ip gerilmesi', '80 N büyüklüğünde ip gerilmesi'], 'O noktasına göre tork: (T · sin30°) · 0,40 = 20 · 0,40 + 15 · 0,80 => 0,20 T = 8 + 12 = 20 => T = 100 N bulunur.'),
  ('Eşit bölmeli 6 birimli türdeş bir kalas iki destek üzerinde yatay dengededir. Sol destek 1. bölmede, sağ destek 5. bölmede olup kalasın ağırlığı 60 N\'dur. Sağ uca (6. bölmeye) en fazla kaç N ağırlığında bir kedi çıkarsa kalas sağ destek etrafında devrilmez?', 'En fazla 120 N ağırlığında olabilir', ['En fazla 60 N ağırlığında olabilir', 'En fazla 90 N ağırlığında olabilir', 'En fazla 180 N ağırlığında olabilir'], 'Sağ destek (5. bölme) etrafında devrilme sınırında sol destek tepkisi sıfır olur. Kalas ağırlığı 3. bölmede (sağ desteğe 2 br solda), kedi 6. bölmede (1 br sağda): G_kedi · 1 = 60 · 2 => 120 N.'),
  ('Bir sokak lambası, karşılıklı iki apartman duvarı arasına gerilen iki çelik halatın kesişim noktasına asılarak dengelenmiştir. Halatlardan biri yatayla 37°, diğeri 53° açı yaptığına ve lambanın ağırlığı 150 N olduğuna göre 53° açı yapan halattaki gerilme kaç N\'dur? (sin37° = 0,6; sin53° = 0,8)', '120 N gerilme oluşur', ['90 N gerilme oluşur', '150 N gerilme oluşur', '100 N gerilme oluşur'], 'İki halat arasındaki açı 180° - (37° + 53°) = 90°\'dir. Lami teoreminden T₅₃ = G · cos37° = 150 · 0,8 = 120 N bulunur.'),
  ('Kesişen üç kuvvetin etkisinde statik dengede bulunan noktasal bir cisim için Lami teoremi uygulandığında, kuvvet büyüklükleri ile karşılarındaki açılar (90° ile 180° arasındaki geniş açılar) arasındaki genel kural aşağıdakilerden hangisidir?', 'Karşısındaki geniş açısı en küçük olan kuvvet en büyüktür', ['Karşısındaki geniş açısı en büyük olan kuvvet en büyüktür', 'Üç kuvvetin büyüklüğü açılardan bağımsız biçimde birbirine eşittir', 'Kuvvet büyüklükleri karşılarındaki açıların kosinüsleriyle orantılıdır'], '90°–180° aralığında açı büyüdükçe sinüs değeri küçülür; F/sinα sabit olduğundan küçük geniş açının karşısındaki kuvvet daha büyüktür.'),
  ('Yatay bir tavana K ve L noktalarından bağlı iki özdeş ipin alt uçları O düğüm noktasında birleştirilip buraya P ağırlıklı bir avize asılmıştır. K noktasındaki bağlantı sökülüp ipin boyu uzatılarak tavanda daha sol bir M noktasına bağlanırsa (O noktası biraz aşağı kayarak ipler arası açı büyürse) iplerdeki toplam gerilme nasıl etkilenir?', 'İpler arasındaki açı büyüdüğü için her iki ipteki gerilme de artar', ['Avizenin ağırlığı değişmediğinden ip gerilmeleri sabit kalır', 'İpler uzadığı için esneklik artar ve her iki gerilme de azalır', 'Yalnızca düşeyle küçük açı yapan ipteki gerilme kuvveti sıfırlanır'], 'Sabit bir düşey yükü dengeleyen simetrik veya açılan iki ip arasındaki açı arttıkça düşey bileşen katsayısı (cosθ) küçülür, dolayısıyla T gerilmeleri büyür.'),
  ('Ağırlığı 180 N olan bir hasta sedyesi, boyu 2 m olan düzgün bir gövdeye sahiptir; ancak hastanın üst gövdesi nedeniyle sedye+hasta sisteminin toplam ağırlığı 900 N olup ağırlık merkezi baş kısmından 80 cm içeridedir. Baş ve ayak uçlarından tutan iki sağlık görevlisinin taşıdığı düşey yükler kaçar N\'dur?', 'Baş ucundaki 540 N, ayak ucundaki 360 N taşır', ['Baş ucundaki 360 N, ayak ucundaki 540 N taşır', 'Her iki görevli de eşit olarak 450 N yük taşır', 'Baş ucundaki 600 N, ayak ucundaki 300 N taşır'], 'Ayak ucuna (200. cm) göre tork alınırsa baş ucundaki yük F_bas · 200 = 900 · (200 - 80) = 900 · 120 => F_bas = 540 N; ayak ucu = 900 - 540 = 360 N.'),
  ('Sürtünmesiz düşey iki duvar arasına sıkışmadan yerleştirilen özdeş olmayan kürelerden alt küre yatay zemine, yanlardan da duvarlara yaslı konularak statik denge incelendiğinde; tek bir iple düşey duvara asılı R = 15 cm yarıçaplı, 60 N ağırlıklı pürüzsüz küreyi tutan ipin boyu 10 cm ise duvarın küreye tepkisi kaç N\'dur?', '45 N büyüklüğünde yatay tepki', ['80 N büyüklüğünde yatay tepki', '100 N büyüklüğünde yatay tepki', '36 N büyüklüğünde yatay tepki'], 'Küre merkezi duvardan R = 15 cm uzakta, ip+yarıçap hipotenüsü 10 + 15 = 25 cm\'dir; düşey dik kenar √(25² - 15²) = 20 cm olur. tanθ = 15/20 = 3/4 => N = G·tanθ = 60·(3/4) = 45 N.'),
  ('Eşit bölmeli homojen olmayan 6 bölmeli bir çubuk, soldan 2. bölmeden tek bir iple tavana asıldığında yatay dengede kalmaktadır. Aynı çubuk uçlarından iki düşey iple tavana asılırsa sol ipteki gerilmenin sağ ipteki gerilmeye oranı (T_sol / T_sağ) kaç olur?', 'Oran 2 değerine eşittir', ['Oran 1/2 değerine eşittir', 'Oran 3 değerine eşittir', 'Oran 3/2 değerine eşittir'], 'Tek iple 2. bölmeden dengede kaldığına göre ağırlık merkezi soldan 2 br, sağdan 4 br içeridedir. Uçlardan asıldığında T_sol · 2 = T_sağ · 4 => T_sol / T_sağ = 2 olur.'),
  ('Kışın elektrik iletim tellerinin üzerinde buz birikmesi ve aynı zamanda soğuktan büzülen telin gerginleşerek sarkma miktarının (sehim) azalması tellerin kopma riskini neden çift yönlü artırır?', 'Hem düşey yük büyüdüğü hem de telin yatayla yaptığı açı küçüldüğü için', ['Soğuk havada bakır ve alüminyumun özkütlesi yarı yarıya azaldığı için', 'Direkler arasındaki yatay uzaklık kış aylarında iki katına çıktığı için', 'Yerçekimi ivmesi buz kütlesine yalnızca yatay doğrultuda etki ettiği için'], 'Tel gerilmesi T = G_toplam / (2·sinα) ile bulunur. Buz yükü G\'yi artırırken büzülme sarkma açısı α\'yı küçültür; her iki etki de T\'yi hızla büyütür.'),
  ('Bir tablo arkasındaki iki kancaya bağlanan tek bir ipin orta noktasından duvardaki çiviye asılmaktadır. Ressam ipi kısaltarak kancalarla çivi arasındaki açıyı 60° yerine 120° yaparsa, ipin kopmaya karşı güvenliği ve çivinin taşıdığı net düşey kuvvet nasıl değişir?', 'İp gerilmesi artacağından kopma riski büyür; çivideki net kuvvet değişmez', ['İp kısaldığı için gerilme azalır; çivideki net kuvvet yarıya iner', 'İp gerilmesi sabit kalırken çivinin taşıdığı net kuvvet kök üç katına çıkar', 'Hem ip gerilmesi hem de çivinin tabloya uyguladığı bileşke tepki azalır'], 'Çivi her durumda tablonun toplam ağırlığını (G) taşır; fakat iki ip kolu arasındaki açı 60°\'den 120°\'ye çıktığında ip gerilmesi G/√3 değerinden G değerine yükselir.'),
  ('Tavana asılı esnemeyen bir ipin ucundaki 80 N ağırlıklı demir küreye yatay doğrultuda sabit F kuvveti uygulanarak ip düşeyle 37° açı yapacak konumda dengeleniyor. Bu durumda F kuvvetinin büyüklüğü ile ipteki T gerilmesinin toplamı kaç N\'dur? (sin37° = 0,6; cos37° = 0,8)', 'Toplamları 160 N değerine eşittir', ['Toplamları 140 N değerine eşittir', 'Toplamları 128 N değerine eşittir', 'Toplamları 180 N değerine eşittir'], 'T · cos37° = 80 => 0,8 T = 80 => T = 100 N; F = T · sin37° = 100 · 0,6 = 60 N. İkisinin skaler toplamı 60 + 100 = 160 N olur.'),
  ('Üst üste konulmuş özdeş ve türdeş iki küre, düşey ve pürüzsüz paralel iki duvar arasında dengededir (duvarlar arası mesafe küre çapından büyük, iki küre çapından küçüktür). Her bir kürenin ağırlığı G olduğuna göre yatay tabanın alttaki küreye uyguladığı normal tepki kuvveti kaç G olur?', '2G büyüklüğünde düşey tepki uygular', ['G büyüklüğünde düşey tepki uygular', '3G/2 büyüklüğünde düşey tepki uygular', 'G√3 büyüklüğünde düşey tepki uygular'], 'Duvarlar pürüzsüz olduğundan düşey sürtünme kuvveti yoktur; tüm sistemi dışarıdan incelediğimizde iki kürenin toplam ağırlığı olan 2G yalnızca yatay tabanın normal tepkisiyle dengelenir.'),
  ('Ağırlığı G olan bir saksı, tavana bağlı iki iple asılarak dengelenmiştir. Sağdaki ip yatayla 60°, soldaki ip yatayla 30° açı yapmaktadır. Saksının içine biraz su eklenerek toplam ağırlık artırıldığında hangi ip kopma sınırına daha önce ulaşır? (İpler özdeştir)', 'Yatayla 60° açı yapan dik konumdaki sağ ip önce kopar', ['Yatayla 30° açı yapan yatık konumdaki sol ip önce kopar', 'İpler özdeş olduğundan her ikisi de aynı anda kopar', 'Düşey yük yalnızca düğüm noktasındaki halkayı koparır'], 'T_sağ = G·sin60° ve T_sol = G·sin30° olduğundan dik duran (düşeye daha yakın olan, yatayla 60° yapan) sağ ipteki gerilme √3 kat daha büyüktür ve önce kopar.'),
  ('Uzunluğu 1,8 m olan kendi içinde türdeş olmayan bir mızrak, arka ucundan 60 cm uzaklıktaki noktadan parmak üzerine konulduğunda yatay dengede kalıyor. Mızrak iki ucundan iki dinamometre ile yatay tutulduğunda arka uçtaki dinamometre 16 N gösteriyorsa mızrağın toplam ağırlığı kaç N\'dur?', 'Mızrağın toplam ağırlığı 24 N\'dur', ['Mızrağın toplam ağırlığı 32 N\'dur', 'Mızrağın toplam ağırlığı 48 N\'dur', 'Mızrağın toplam ağırlığı 20 N\'dur'], 'Kütle merkezi arka uçtan 0,6 m, ön uçtan 1,2 m uzaktadır. Ön uca göre tork: 16 · 1,8 = G · 1,2 => 28,8 = 1,2 G => G = 24 N bulunur.'),
  ('Tavana bağlı bir ipin ucuna ağırlığı önemsiz bir makara değil, sabit bir halka takılmış ve halkadan geçirilen ikinci bir ipin iki ucuna da 30 N\'luk özdeş yükler asılarak kollar arasında 60° açı yapacak biçimde sürtünmesiz kılavuzlarla açılmıştır (halka ortadadır). Halkayı tavana bağlayan üst ipteki gerilme kaç N olur? (cos30° = √3/2)', '30√3 N büyüklüğünde gerilme oluşur', ['60 N büyüklüğünde gerilme oluşur', '30 N büyüklüğünde gerilme oluşur', '45 N büyüklüğünde gerilme oluşur'], 'İki koldaki ip gerilmesi de 30 N olup aralarındaki açı 60°\'dir. İkisinin bileşkesi 2 · 30 · cos30° = 30√3 N aşağı doğrudur ve üst ip bunu dengeler.'),
  ('Paralel ve aynı yönlü üç kuvvet 4 m uzunluğundaki ağırlıksız çubuğun sol ucuna (10 N), orta noktasına (20 N) ve sağ ucuna (30 N) dik olarak uygulanıyor. Bu üç kuvveti tek başına dengeleyecek kuvvetin büyüklüğü ve sol uca uzaklığı nedir?', 'Zıt yönde 60 N ve sol uçtan 8/3 m uzakta', ['Zıt yönde 60 N ve sol uçtan 7/3 m uzakta', 'Aynı yönde 60 N ve sol uçtan 8/3 m uzakta', 'Zıt yönde 40 N ve sol uçtan 2 m uzakta'], 'Bileşke R = 10 + 20 + 30 = 60 N olup sol uca göre torktan 60 · x = 10·0 + 20·2 + 30·4 = 160 => x = 8/3 m bulunur; dengeleyen kuvvet zıt yöndedir.'),
  ('Ağırlığı 20 N olan düzgün türdeş bir çubuk, sol ucundan tavana bağlı T₁ ipiyle ve sağ ucundan 2 bölme içeriden tavana bağlı T₂ ipiyle (toplam 6 bölmeli) yatay dengededir. Çubuğun sağ ucuna (6. bölmeye) kaç N ağırlığında bir cisim asılırsa T₁ ipindeki gerilme tam sıfır olur?', 'Sağ uca 10 N ağırlığında cisim asılmalıdır', ['Sağ uca 20 N ağırlığında cisim asılmalıdır', 'Sağ uca 15 N ağırlığında cisim asılmalıdır', 'Sağ uca 30 N ağırlığında cisim asılmalıdır'], 'T₁ = 0 olduğunda sistem yalnızca 4. bölmedeki T₂ ipiyle dengelenir. Çubuk ağırlığı (20 N) 3. bölmededir (T₂\'ye 1 br solda), sağ uç 6. bölmededir (T₂\'ye 2 br sağda): G · 2 = 20 · 1 => G = 10 N.'),
  ('Bir dağcı iki kayalık yamaç arasına gerdiği emniyet ipinin tam ortasına kendi karabinasını taktığında ip iki taraftan da yatayla 10° gibi küçük bir açı yapmaktadır. Dağcının ağırlığı G olduğuna göre halattaki gerilmenin G\'den yaklaşık kaç kat büyük çıkması beklenir? (sin10° ≈ 0,17)', 'Yaklaşık 3 katı kadar (G / 0,34) büyük çıkar', ['Yaklaşık yarısı kadar (0,5 G) küçük çıkar', 'Dağcının ağırlığına tam eşit (1,0 G) çıkar', 'Yaklaşık 10 katı kadar (10 G) büyük çıkar'], '2 · T · sin10° = G => 2 · 0,17 · T = 0,34 T = G => T ≈ 2,94 G (yaklaşık 3 katı) gerilme oluşur; bu nedenle yatay emniyet hatları aşırı gerilir.'),
  ('Kütlesi m olan özdeş 4 tuğla, harç kullanılmadan bir masanın kenarında üst üste ancak biraz dışarı taşacak biçimde istiflenerek \'Lir kulesi\' (maksimum taşma) problemi oluşturuluyor. En üstteki tek tuğla bir altındaki tuğlanın kenarından devrilmeden en fazla ne kadar dışarı taşabilir? (Tuğla boyu L\'dir)', 'Kendi boyunun yarısı olan L/2 kadar taşabilir', ['Kendi boyunun dörtte biri olan L/4 kadar taşabilir', 'Kendi boyunun üçte biri olan L/3 kadar taşabilir', 'Kendi boyunun tamamı olan L kadar taşabilir'], 'En üstteki tuğlanın kütle merkezi tam ortasında olduğundan, altındaki tuğlanın kenar hizasını geçmemek şartıyla en çok L/2 kadar dışarı taşabilir.'),
  ('Sürtünmesiz bir halka içinden geçen tek bir ipin bir ucu sol duvara yatay bağlanmış, diğer ucu ise halkadan geçtikten sonra düşey aşağı sarkıtılarak ucuna 50 N\'luk yük asılmıştır. Halkayı sağ üst yönde çeken dış F kuvveti sistemi bu konumda dengede tuttuğuna göre F kuvvetinin büyüklüğü kaç N\'dur?', '50√2 N büyüklüğünde kuvvet gerekir', ['50 N büyüklüğünde kuvvet gerekir', '100 N büyüklüğünde kuvvet gerekir', '25√2 N büyüklüğünde kuvvet gerekir'], 'Aynı ip üzerinde gerilme her yerde 50 N\'dur. Halkayı sola 50 N ve aşağı 50 N çeken birbirine dik iki ip kolunun bileşkesi 50√2 N olduğundan dengeleyici F = 50√2 N olur.'),
  ('Tavana asılı A ve B makaralarından geçen iplerle kurulan klasik Lami düzeneğinde, ortadaki düğüm noktasına asılı G_3 yükü sol ve sağ iplerdeki G_1 ve G_2 yükleriyle dengelenmiştir. Sol ip düşeyle α, sağ ip düşeyle β açısı yaparken G_1 = G_2 ise α ve β açıları ile G_3 hakkında hangisi kesinlikle doğrudur?', 'α = β eşitliği vardır ve G_3 < 2 G_1 koşulu sağlanır', ['α = β eşitliği vardır ve G_3 = 2 G_1 koşulu sağlanır', 'α > β eşitsizliği vardır ve G_3 > 2 G_1 koşulu sağlanır', 'Açılar eşit olamaz ancak G_3 = G_1√2 olmak zorundadır'], 'Yatay bileşenlerin eşitliğinden G₁·sinα = G₂·sinβ => α = β çıkar. Düşeyde G₃ = 2·G₁·cosα olup α > 0° için cosα < 1 olduğundan G₃ < 2G₁ bulunur.'),
  ('Ağırlığı G olan düzgün türdeş bir küre, düşey bir duvara yaslanmış ve merkezinden geçen doğrultudaki bir iple duvara bağlanmıştır. İpin duvarla yaptığı dar açı 30° iken ip boyu kısaltılarak açı 53° yapılırsa ipteki gerilme ve duvar tepkisi nasıl değişir?', 'Açı büyüdüğü için hem ip gerilmesi hem duvar tepkisi artar', ['İp gerilmesi artarken duvarın normal tepki kuvveti azalır', 'İp kısaldığı için hem ip gerilmesi hem duvar tepkisi azalır', 'İp gerilmesi sabit kalırken duvarın tepki kuvveti artar'], 'T = G / cosθ ve N = G · tanθ bağıntılarında θ açısı 30°\'den 53°\'ye büyüdüğünde cosθ küçülür (T artar) ve tanθ büyür (N artar).'),
  ('İki işçi 3 m uzunluğundaki 600 N ağırlıklı türdeş çelik boruyu omuzlarında yatay olarak taşımaktadır. Öndeki işçi borunun ön ucundan 50 cm geriden, arkadaki işçi ise arka uçtan 100 cm ileriden omuzladığına göre hangi işçi kaç N yük taşır?', 'Öndeki işçi 240 N, arkadaki işçi 360 N taşır', ['Öndeki işçi 360 N, arkadaki işçi 240 N taşır', 'Öndeki işçi 200 N, arkadaki işçi 400 N taşır', 'Her iki işçi de eşit olarak 300 N yük taşır'], 'Kütle merkezi 150. cm\'dedir. Öndeki işçi 50. cm\'de (merkeze 100 cm), arkadaki işçi 200. cm\'dedir (merkeze 50 cm). N_ön·100 = N_arka·50 => N_arka = 2 N_ön ve toplam 600 N => 240 N ve 360 N.'),
  ('Ağırlıkları sırasıyla 20 N ve 30 N olan K ve L küreleri esnemeyen iplerle tavana alt alta asılmak yerine, tavan ile zemin arasına gerilmiş düşey bir yay ve ip sistemiyle dengeleniyor: Tavana bağlı üst ip K küresini (20 N) tutmakta, K ile L arasındaki hafif yay 15 N çekme kuvvetiyle gerilmiş durumda bulunmakta ve L küresi (30 N) yatay zemin üzerinde durmaktadır. Buna göre üst ipteki gerilme ile zeminin L küresine tepkisi nedir?', 'Üst ip 35 N gerilir, zemin L\'ye 15 N tepki gösterir', ['Üst ip 50 N gerilir, zemin L\'ye 0 N tepki gösterir', 'Üst ip 20 N gerilir, zemin L\'ye 30 N tepki gösterir', 'Üst ip 35 N gerilir, zemin L\'ye 45 N tepki gösterir'], 'Çekme durumundaki yay K\'yi 15 N aşağı çeker: T_üst = 20 + 15 = 35 N. Aynı yay L\'yi 15 N yukarı çeker: N_zemin = 30 - 15 = 15 N olur.'),
  ('Düzgün türdeş bir kalasın sol ucu yatay pürüzlü zeminde, gövdesi ise yerden h yüksekliğindeki sürtünmesiz yatay bir korkuluk demirinin üzerinde eğik olarak yaslı ve dengededir. Korkuluk demirinin kalasa uyguladığı tepki kuvvetinin yönü hakkında ne söylenebilir?', 'Sürtünmesiz olduğundan kalasın kendi doğrultusuna tam diktir', ['Yerçekimi doğrultusuna paralel olup tam düşey yukarı doğrudur', 'Yatay zemine paralel olup sola doğru yönelmiş durumdadır', 'Kalasın kütle merkezinden zemindeki temas noktasına doğrudur'], 'Noktasal/çizgisel bir destek yüzeyinde sürtünme yoksa temas tepkisi (normal kuvvet) üzerine yaslanan çubuğun yüzeyine diktir.'),
  ('Kütlesi 4 kg olan bir saksı, tavana 53° açıyla bağlı esnemeyen bir ip ve düşey duvara dik sabitlenmiş yatay bir yay ile dengede tutulmaktadır (yay uzamış durumdadır). Yay sabiti k = 300 N/m olduğuna göre yayın uzama miktarı kaç cm\'dir? (g = 10 m/s²; sin53° = 0,8; cos53° = 0,6)', 'Yay 10 cm kadar uzamıştır', ['Yay 15 cm kadar uzamıştır', 'Yay 8 cm kadar uzamıştır', 'Yay 12 cm kadar uzamıştır'], 'T · sin53° = 40 N => 0,8 T = 40 => T = 50 N. Yatayda F_yay = T · cos53° = 50 · 0,6 = 30 N. Hooke yasasından 30 = 300 · x => x = 0,10 m = 10 cm.'),
  ('İki ucundan özdeş K ve L yaylarıyla tavana yatay olarak asılmış homojen olmayan 1 m uzunluğundaki çubuk dengedeyken K yayı 4 cm, L yayı 6 cm uzamıştır. Buna göre çubuğun kütle merkezi sol uçtaki K yayından kaç cm uzaktadır?', 'K yayından 60 cm uzaktadır', ['K yayından 40 cm uzaktadır', 'K yayından 50 cm uzaktadır', 'K yayından 66,7 cm uzaktadır'], 'Özdeş yaylarda kuvvet uzamayla orantılıdır: F_K / F_L = 4 / 6 = 2 / 3. Kütle merkezi büyük kuvvete daha yakındır: 2 · x = 3 · (100 - x) => 5x = 300 => x = 60 cm.'),
  ('Aynı düzlemde yer alan kesişen üç kuvvetten F₁ ile F₂ arasındaki açı α olup üç kuvvet dengededir. F₃ kuvvetinin büyüklüğü sabit kalmak koşuluyla F₁ ve F₂ kuvvetlerinin büyüklükleri eşit oranda artırılırsa yeni dengenin sağlanabilmesi için α açısı nasıl değiştirilmelidir?', 'Bileşkelerinin küçülüp F₃\'e eşit kalması için α açısı büyütülmelidir', ['Bileşkelerinin büyümesi için α açısı daraltılarak sıfıra yaklaştırılmalıdır', 'Kuvvetler aynı oranda arttığından α açısı hiç değiştirilmemelidir', 'α açısı her durumda 90° dik açı değerine sabitlenmelidir'], 'Sabit bir F₃ değerini dengeleyecek F₁ ve F₂\'nin kendileri büyüdüğünde bileşkelerinin aynı kalması için aralarındaki α açısının büyütülmesi gerekir.'),
  ('Eşit bölmeli 6 bölmeli türdeş K çubuğunun ağırlığı 24 N, 4 bölmeli türdeş L çubuğunun ağırlığı 16 N\'dur. L çubuğu yatay bir masa üzerinde tam ortasından desteklenmişken K çubuğunun sağ ucu L\'nin sol ucuna konularak K\'nin sol ucu da yerde ayrı bir desteğe oturtuluyor (her iki çubuk da yataydır). L çubuğunun yatay dengesinin bozulmaması için sağ ucuna kaç N yük konulmalıdır?', 'L\'nin sağ ucuna 12 N yük konulmalıdır', ['L\'nin sağ ucuna 24 N yük konulmalıdır', 'L\'nin sağ ucuna 8 N yük konulmalıdır', 'L\'nin sağ ucuna 16 N yük konulmalıdır'], 'Türdeş K çubuğu (24 N) iki ucundan desteklendiği için L\'nin sol ucuna 24/2 = 12 N bastırır. L tam ortasından destekli olduğundan simetri gereği L\'nin sağ ucuna da 12 N konulmalıdır.'),
  ('Düşey duvardaki K noktasına bağlı bir ipin ucunda O merkezli türdeş küre asılı olup küre duvara değerek dengededir. Kürenin yarıçapı sabit tutulup yalnızca kütlesi iki katına çıkarılırsa (aynı boyutta daha yoğun metal küre asılırsa) ipin duvarla yaptığı açı, ip gerilmesi ve duvar tepkisi nasıl değişir?', 'Açı değişmez; ip gerilmesi ve duvar tepkisi iki katına çıkar', ['Açı iki katına çıkar; ip gerilmesi ve duvar tepkisi sabit kalır', 'Açı küçülür; ip gerilmesi artarken duvar tepkisi yarıya iner', 'Açı değişmez; ip gerilmesi dört katına, duvar tepkisi iki katına çıkar'], 'Açı yalnızca ip boyu ve küre yarıçapına (geometriye) bağlı olduğundan değişmez; T = G/cosθ ve N = G·tanθ gereği G iki katına çıkınca ikisi de iki katına çıkar.'),
  ('Bir inşaat vinci, prefabrik beton bir duvar panelini üst kenarındaki iki mapadan geçen özdeş iki çelik sapanla kaldırmaktadır. Sapan boyları 5 m, iki mapa arasındaki yatay mesafe 6 m ve panel ağırlığı 48 kN olduğuna göre her bir sapandaki gerilme kaç kN\'dur? (Sabit hızla kaldırılmaktadır)', 'Her bir sapanda 30 kN gerilme oluşur', ['Her bir sapanda 24 kN gerilme oluşur', 'Her bir sapanda 40 kN gerilme oluşur', 'Her bir sapanda 36 kN gerilme oluşur'], 'Yatay yarı mesafe 3 m, sapan boyu 5 m ise düşey yükseklik 4 m\'dir (sinα = 4/5). 2 · T · (4/5) = 48 => 1,6 T = 48 => T = 30 kN bulunur.'),
  ('Pürüzsüz düşey bir duvara dayalı duran merdivenin alt ucunun pürüzsüz bir buz yüzeyi üzerinde olması durumunda (hem duvar hem zemin sürtünmesiz) merdiveni eğik konumda serbest bıraktığımızda neden statik denge kurulamaz?', 'Duvarın yatay normal tepkisini dengeleyecek hiçbir zıt yatay kuvvet bulunmadığı için', ['Yerçekimi kuvveti sürtünmesiz ortamda tork üretme özelliğini kaybettiği için', 'Zeminin düşey normal tepkisi merdiven ağırlığından her zaman büyük çıktığı için', 'Merdivenin kütle merkezi duvara değmediği sürece ağırlık sıfır olduğu için'], 'Eğik merdivende ağırlığın alt uca göre torkunu dengelemek için duvar mutlaka yatay bir normal tepki (N_duvar > 0) uygulamalıdır; zeminde sürtünme yoksa bu yatay kuvveti sıfırlayacak zıt kuvvet yoktur.'),
  ('Uzunluğu 80 cm olan düzgün türdeş bir çubuğun bir ucuna 10 N, diğer ucuna 30 N ağırlığında iki cisim asılmıştır. Çubuk kendi orta noktasından 10 cm uzaktaki bir noktadan desteklendiğinde yatay dengede kaldığına göre çubuğun kendi ağırlığı kaç N\'dur?', 'Çubuğun kendi ağırlığı 40 N\'dur', ['Çubuğun kendi ağırlığı 20 N\'dur', 'Çubuğun kendi ağırlığı 60 N\'dur', 'Çubuğun kendi ağırlığı 50 N\'dur'], 'Orta nokta 40. cm\'dir; büyük yüke (30 N, sağ uç 80. cm) yakın olan destek 50. cm\'dedir. Desteğe göre tork: 30 · 30 = 10 · 50 + G · 10 => 900 = 500 + 10G => G = 40 N.'),
  ('Kütlesi 6 kg olan homojen bir küre, aralarındaki açı 90° olan iki pürüzsüz düzlem arasına konulmuştur. Düzlemlerden biri yatayla 37°, diğeri 53° açı yaptığına göre 53° eğimli dikeyimsi düzlemin küreye uyguladığı tepki kuvveti kaç N\'dur? (g = 10 m/s²; sin37° = 0,6; cos37° = 0,8)', '36 N büyüklüğünde tepki uygular', ['48 N büyüklüğünde tepki uygular', '60 N büyüklüğünde tepki uygular', '45 N büyüklüğünde tepki uygular'], 'Düzlemler dik kesiştiğinden normalleri de diktir. 53° eğimli yüzeyin normali düşeyle 53° açı yapar: N₅₃ = m·g·cos53° = 60 · 0,6 = 36 N bulunur.'),
  ('Bir asma köprünün ana taşıyıcı çelik kabloları kuleler arasında parabolik bir eğri oluşturacak biçimde sarkıtılır. Kulelerin yüksekliği daha kısa tasarlanıp kablolar daha gergin (daha az sarkık) çekilseydi kabloların ve kule temellerinin maruz kalacağı kuvvetler nasıl değişirdi?', 'Kablolardaki çekme gerilmesi artar, kulelere binen yanal çekme büyürdü', ['Kablo boyu kısaldığı için kablo gerilmesi yarı yarıya azalırdı', 'Yalnızca kulelerin düşey basma yükü iki katına çıkardı', 'Köprü tabliyesinin toplam ağırlığı azalacağından gerilme düşerdi'], 'Kule yüksekliği azaldığında kablonun yatayla yaptığı eğim açısı küçülür; aynı düşey tabliye yükünü taşımak için kablo gerilmesi ve yatay ankraj çekmesi büyük ölçüde artar.'),
  ('Tavana asılı ağırlıksız eşit bölmeli 7 bölmeli bir çubuk, soldan 3. bölmesinden tek bir iple asılıdır. Sol uca (0. nokta) 20 N, 1. bölmeye 15 N yük asıldığında sağ tarafta yalnızca 6. bölmeye kaç N yük asılırsa yatay denge sağlanır ve üst ipteki gerilme ne olur?', '30 N yük asılır; üst ip gerilmesi 65 N olur', ['25 N yük asılır; üst ip gerilmesi 60 N olur', '30 N yük asılır; üst ip gerilmesi 35 N olur', '35 N yük asılır; üst ip gerilmesi 70 N olur'], '3. bölmeye göre tork: 20·3 + 15·2 = G · (6 - 3) => 60 + 30 = 3G => G = 30 N. Üst ip tüm yükleri taşır: T = 20 + 15 + 30 = 65 N.'),
  ('Yatay düzlemdeki K ve L destekleri üzerinde duran 6 m uzunluğundaki türdeş kalasın sol ucu K desteğinde, sağ ucu ise L desteğinden 2 m dışarı taşmış durumdadır (yani K ile L arası 4 m\'dir). Kalasın ağırlığı 120 N olduğuna göre sağ uca 40 N\'luk bir yük konulduğunda K desteğinin tepkisi kaç N olur?', 'K desteğinin tepkisi 10 N olur', ['K desteğinin tepkisi 20 N olur', 'K desteğinin tepkisi 30 N olur', 'K desteğinin tepkisi 15 N olur'], 'L desteğine (4. m) göre tork alınırsa: Kalas ağırlığı 3. m\'de (L\'ye 1 m solda), 40 N yük 6. m\'de (L\'ye 2 m sağda), K desteği 0. m\'de (L\'ye 4 m solda): N_K·4 + 40·2 = 120·1 => 4 N_K + 80 = 120 => N_K = 10 N.'),
  ('Eşit bölmeli 5 bölmeli türdeş bir çubuk, sol ucundan 1 bölme içerideki ipe ve sağ ucundaki desteğe dayanarak yatay dengede durmaktadır. İpteki gerilme kuvveti 30 N olduğuna göre çubuğun kendi ağırlığı ve sağ uçtaki desteğin tepkisi kaçar N\'dur?', 'Çubuk ağırlığı 48 N, destek tepkisi 18 N\'dur', ['Çubuk ağırlığı 40 N, destek tepkisi 10 N\'dur', 'Çubuk ağırlığı 60 N, destek tepkisi 30 N\'dur', 'Çubuk ağırlığı 45 N, destek tepkisi 15 N\'dur'], '5 bölmeli çubuğun kütle merkezi 2,5. bölmededir; ip 1. bölmede, destek 5. bölmededir. Desteğe göre tork: 30 · (5 - 1) = G · (5 - 2,5) => 120 = 2,5 G => G = 48 N; N = 48 - 30 = 18 N.'),
  ('Ağırlığı 90 N olan bir avize, tavandaki K ve L noktalarına bağlı birbirine dik iki zincirle dengelenmiştir. K zinciri tavanla 30°, L zinciri tavanla 60° açı yaptığına göre K zincirindeki gerilme kuvvetinin L zincirindeki gerilme kuvvetine oranı (T_K / T_L) kaçtır?', 'Oran 1/√3 (yani √3/3) değerindedir', ['Oran √3 değerindedir', 'Oran 1/2 değerindedir', 'Oran 2 değerindedir'], 'Yatay bileşenlerin eşitliğinden T_K · cos30° = T_L · cos60° => T_K · (√3/2) = T_L · (1/2) => T_K / T_L = 1/√3 bulunur.'),
  ('Deniz seviyesinden yükselen çok katlı bir gökdelenin geometrik simetri merkezi olan kütle merkezi ile ağırlık merkezinin düşey konumları karşılaştırıldığında aşağıdakilerden hangisi doğrudur?', 'Ağırlık merkezi kütle merkezinin çok az aşağısındadır', ['Kütle merkezi ağırlık merkezinin birkaç metre aşağısındadır', 'Her iki merkez yükseklikten bağımsız olarak tam çakışıktır', 'Üst katlar daha çok çekildiği için ağırlık merkezi yukarıdadır'], 'Yerden yükseldikçe yerçekimi ivmesi g azaldığından gökdelenin alt kısımları birim kütle başına daha büyük ağırlığa sahiptir; bu yüzden ağırlık merkezi kütle merkezinin biraz altında kalır.'),
  ('Uzunluğu 80 cm olan düzgün türdeş bir telin sağ ucundan 20 cm\'lik kısmı kesilerek atılmak yerine kendi üzerine katlanarak çift kat yapılıyor. Telin kütle merkezi ilk konumuna göre hangi yönde ve kaç cm yer değiştirir?', '5 cm sol tarafa doğru yer değiştirir', ['10 cm sol tarafa doğru yer değiştirir', '5 cm sağ tarafa doğru yer değiştirir', 'Katlanan kısım telde kaldığı için hiç değişmez'], 'İlk kütle merkezi 40. cm\'dedir. Katlama sonrası 0–40 cm arası (40 br, merkez 20) ve 40–60 cm arası çift kat (40 br, merkez 50) olur: x_km = (40·20 + 40·50)/80 = 35. cm; yani sola 5 cm kayar (Δx = x²/L = 400/80 = 5 cm).'),
  ('Yarıçapları r ve 2r olan aynı telden yapılmış iki çember dıştan tek bir noktada birbirine teğet olacak biçimde kaynak yapılıyor. Birleşik tel sisteminin kütle merkezi küçük çemberin merkezinden kaç r uzaktadır?', 'Küçük çember merkezinden 2r uzaktadır', ['Küçük çember merkezinden r uzaktadır', 'Küçük çember merkezinden 9r/5 uzaktadır', 'Küçük çember merkezinden 12r/5 uzaktadır'], 'Tel kütleleri çevrelerle orantılıdır: m₁ = 2πr (k) ve m₂ = 2π(2r) = 2k. Merkezler arası mesafe r + 2r = 3r\'dir. Küçük merkezden uzaklık: x = (2k · 3r) / (k + 2k) = 2r bulunur.'),
  ('Aynı maddeden yapılmış r ve 2r yarıçaplı iki dolu küre dıştan birbirine teğet olacak biçimde yapıştırılırsa birleşik katı cismin kütle merkezi büyük kürenin merkezinden kaç r uzakta bulunur?', 'Büyük küre merkezinden r/3 uzaktadır', ['Büyük küre merkezinden 3r/5 uzaktadır', 'Büyük küre merkezinden r/2 uzaktadır', 'Büyük küre merkezinden r/9 uzaktadır'], 'Dolu kürelerde kütle hacimle (r³) orantılıdır: m₁ = m ve m₂ = 8m. Merkezler arası uzaklık 3r olduğundan büyük merkeze uzaklık: x = (m · 3r) / (m + 8m) = 3r/9 = r/3 olur.'),
  ('Yarıçapı 6R olan türdeş dairesel bir karton levhadan, bir kenarı büyük dairenin çevresine içten teğet olan 2R yarıçaplı küçük bir daire kesilip çıkarılıyor. Kalan parçanın kütle merkezi büyük dairenin merkezinden kaç R kayar?', 'Kesilen kısmın tersi yönde R/2 kayar', ['Kesilen kısmın tersi yönde R kadar kayar', 'Kesilen kısma doğru R/2 kayar', 'Kesilen kısmın tersi yönde 4R/9 kayar'], 'Büyük daire alanı 36S (merkez O), çıkarılan daire 4S (merkezi O\'dan 6R - 2R = 4R uzakta). Kalan kütle 32S olup Δx = (4S · 4R) / (36S - 4S) = 16R / 32 = R/2 ters yöne kayar.'),
  ('Yüksek atlama branşında sporcuların çıtayı sırtüstü kavis çizerek geçtikleri \'Fosbury tekniği\' biyomekanik açıdan incelendiğinde geleneksel makas tekniğine göre hangi şaşırtıcı üstünlüğü sağlar?', 'Sporcunun kütle merkezi çıta seviyesinin altından geçerken vücudunun çıtayı aşabilmesi', ['Sporcu havadayken yerçekimi ivmesinin kavisli vücuda etki etmemesi', 'Sıçrama anında sporcunun toplam kütlesinin yarı yarıya azalması', 'Kütle merkezinin parabolik yörünge yerine yatay doğru boyunca ilerlemesi'], 'Vücut ters U biçiminde büküldüğünde kütle merkezi vücudun dışına (sırt kavisinin altına) düşer; böylece aynı sıçrama enerjisiyle kütle merkezi daha alçaktan geçerken gövde daha yüksek çıtayı aşar.'),
  ('Alt kısmı ağır küresel kurşunla doldurulmuş, üst kısmı hafif plastikten yapılmış \'hacıyatmaz\' oyuncağı yana yatırılıp bırakıldığında tekrar dik konuma döner. Bu oyuncağın dik konumdaki denge türü ve geri çağırıcı mekanizması nedir?', 'Kararlı dengedir; yatırıldığında kütle merkezi yükselir ve ağırlık geri döndürücü tork üretir', ['Doğal (nötr) dengedir; yatırıldığında kütle merkezinin yerden yüksekliği hiç değişmez', 'Kararsız dengedir; temas noktası kaydıkça potansiyel enerji sürekli azalır', 'Kararlı dengedir; plastik kısmın kütlesi kurşundan büyük olduğu için üst kısım çeker'], 'Hacıyatmazın kütle merkezi yarım kürenin eğrilik merkezinin altındadır; yana eğildiğinde kütle merkezi yükselir (potansiyel enerji artar) ve temas noktasına göre dikleştirici tork doğar.'),
  ('Eşit kare bölmeli düzlemde türdeş bir levhaya eklemeler veya çıkarmalar yapıldığında levhanın yatay (x) doğrultudaki kütle merkezinin yerinin değişmemesi için eklenen iki özdeş parçanın konumları hangi şartı sağlamalıdır?', 'İlk kütle merkezinden geçen düşey eksene göre yatay uzaklıkları eşit ve zıt tarafta olmalıdır', ['Mutlaka aynı yatay satır üzerinde yan yana bitişik karelerde bulunmalıdır', 'Levhanın yalnızca üst kenarına yapıştırılarak düşey simetriyi bozmalıdır', 'İlk kütle merkezine olan kuş uçuşu uzaklıkları farklı seçilmelidir'], 'x_km konumunun değişmemesi için eklenen parçaların mevcut kütle merkezinden geçen y eksenine (düşey doğruya) göre cebirsel momentleri toplamı sıfır (m·x₁ + m·x₂ = 0 => x₁ = -x₂) olmalıdır.'),
  ('Uzunluğu 12a olan homojen bir tel ortadan 90° bükülerek her bir kolu 6a olan L biçiminde dik açılı bir tel elde ediliyor. Bu telin kütle merkezinin bükülme köşesine (O noktasına) olan kuş uçuşu uzaklığı kaç a\'dır?', '3√2 / 2 a (yani 1,5√2 a) uzaktadır', ['3√2 a kadar uzaktadır', '3 a kadar uzaktadır', '2√2 a kadar uzaktadır'], 'Köşeyi (0,0) seçersek yatay kolun merkezi (3a, 0) ve düşey kolun merkezi (0, 3a) olur. Eşit kütleli iki kolun ortak merkezi (1,5a, 1,5a) noktasındadır; orijine uzaklığı 1,5√2 a = 3√2/2 a bulunur.'),
  ('Birim karelerden oluşturulmuş T harfi biçimindeki türdeş levha; üstte yatay yan yana 3 birim kare ve ortadaki karenin altına dikey eklenmiş 3 birim kareden (toplam 6 özdeş kare) meydana gelmektedir. Karenin bir kenarı 2 cm olduğuna göre sistemin kütle merkezi en alt kenardan kaç cm yukarıdadır?', 'En alt kenardan 5 cm yukarıdadır', ['En alt kenardan 4 cm yukarıdadır', 'En alt kenardan 4,5 cm yukarıdadır', 'En alt kenardan 5,5 cm yukarıdadır'], 'Dikey gövde 3 kare (boyu 6 cm, merkezi alttan 3 cm\'de, kütlesi 3m); üst yatay şapka 3 kare (yüksekliği 6–8 cm arası, merkezi alttan 7 cm\'de, kütlesi 3m). Ortak merkez = (3m·3 + 3m·7) / 6m = 5 cm.'),
  ('Birim kareli düzlemde birbirine yapıştırılmış özdeş 4 kareden oluşan L biçimindeki türdeş bir levha (düşeyde 3 kare, en altta sağa doğru 1 ek kare) yatay zemin üzerine 2 karelik alt tabanı oturacak biçimde konuluyor. Bu levha serbest bırakıldığında dengede kalır mı?', 'Kütle merkezi 2 birimlik taban aralığının içinden geçtiği için dengede kalır', ['Üstteki kareler ağır bastığı için sola doğru devrilir', 'Sağdaki çıkıntı tork ürettiği için sağa doğru devrilir', 'Yalnızca sürtünmesiz zeminlerde dengede kalabilir'], 'Sol kenarı x = 0 alırsak düşeydeki 3 karenin merkezi x₁ = 0,5 br, sağ alttaki 1 karenin merkezi x₂ = 1,5 br olur. Ortak x_km = (3·0,5 + 1·1,5)/4 = 0,75 br olup [0, 2] taban aralığının içindedir; devrilmez!'),
  ('İp cambazlarının ince çelik halat üzerinde yürürken ellerinde uçları aşağı doğru hafifçe sarkan çok uzun ve esnek bir denge sırığı taşımalarının kütle merkezi ve dönme mekaniği bakımından sağladığı iki temel katkı nedir?', 'Ortak kütle merkezini alçaltmak ve eylemsizlik momentini büyütüp devrilmeyi yavaşlatmak', ['Halattaki gerilme kuvvetini azaltmak ve yerçekimi ivmesini sıfırlamak', 'Cambazın ağırlığını azaltarak halat ile ayakkabı arasındaki sürtünmeyi yok etmek', 'Rüzgâr kuvvetini artırarak cambazın halat üzerinde koşmasını hızlandırmak'], 'Uçları aşağı sarkan ağır sırık bir yandan birleşik sistemin kütle merkezini halat seviyesine indirir, diğer yandan büyük eylemsizlik momenti yaratarak yana yatma süresini uzatıp düzeltme fırsatı verir.'),
  ('Kenar uzunlukları 6 cm ve 12 cm olan dikdörtgen biçimindeki türdeş karton levha, tam ortasından katlanmak yerine uzun kenarının üçte birlik kısmı (4 cm\'lik şerit) kendi üzerine katlanarak çift kat yapılıyor. Yeni kütle merkezinin katlanmayan kısa kenara uzaklığı kaç cm olur?', 'Katlanmayan kısa kenardan 14/3 cm uzaktadır', ['Katlanmayan kısa kenardan 5 cm uzaktadır', 'Katlanmayan kısa kenardan 4 cm uzaktadır', 'Katlanmayan kısa kenardan 13/3 cm uzaktadır'], 'Katlanmayan ucu x = 0 alırsak toplam boy 8 cm\'ye düşer: 0–4 cm tek kat (kütle 4m, merkez 2 cm) ve 4–8 cm çift kat (kütle 8m, merkez 6 cm). x_km = (4m·2 + 8m·6) / 12m = 56/12 = 14/3 cm.'),
  ('Taban kenarı a, yüksekliği h olan kare dik prizma biçimindeki türdeş bir tahta blok, eğim açısı giderek artırılan pürüzlü bir eğik düzlem üzerinde kaymadan durmaktadır. Bloğun alt kenarı etrafında devrilmeye başladığı sınır eğim açısı α için tanα değeri neye eşittir?', 'Taban kenarının yüksekliğe oranı olan a / h değerine eşittir', ['Yüksekliğin taban kenarına oranı olan h / a değerine eşittir', 'Taban kenarının yarı yüksekliğe oranı olan 2a / h değerine eşittir', 'Sürtünme katsayısının karesine her zaman sayısal olarak eşittir'], 'Devrilme sınırında merkezden (yatayda a/2, düşeyde h/2) inen düşey ağırlık doğrusu alt köşeden geçer; oluşan dik üçgende tanα = (a/2) / (h/2) = a / h bulunur.'),
  ('Yarıçapı 3r olan O₁ merkezli dairesel türdeş levhadan, merkezi O₂ olan r yarıçaplı küçük bir daire kesilip atılıyor (O₁ ile O₂ arası uzaklık 2r\'dir). Levhanın kalan kısmının kütle merkezinin tekrar O₁ noktasına gelmesi için kesilen boşluğun tam simetriğindeki bölgeyle ilgili aşağıdaki işlemlerden hangisi tek başına yapılabilir?', 'O₁\'e göre simetrik taraftan da O₁\'e 2r uzaklıkta r yarıçaplı özdeş bir daire daha kesip atmak', ['O₁ noktasına alanı πr² olan tek bir dairesel parça yapıştırmak', 'Kesilen boşluğun kenarına alanı 2πr² olan bir daire yapıştırmak', 'Büyük levhanın dış çevresine ince bir çember tel geçirmek'], 'O₁ noktasına göre simetrik konumdan eşit alanlı (πr²) ikinci bir daire çıkarıldığında çıkarılan parçaların ortak merkezi O₁ olur ve kalan levhanın merkezi yine O₁\'de kalır.'),
  ('Özdeş küplerin yüzeylerinden yapıştırılmasıyla oluşturulan 4 küplük bir kulede altta tek bir küp yatay zemine basmakta, diğer üç küp ise her katta yarım küp sağa kaydırılarak merdiven gibi yükselmektedir. Her küp kenarı a olduğuna göre bu 4 küplük yapı zemindeki alt küpün sağ kenarı etrafında devrilir mi?', 'Ortak kütle merkezi alt küpün sağ kenarını (a sınırını) aştığı için devrilir', ['Alt küp tam yere bastığı için kütle merkezi ortada kalır ve devrilmez', 'Toplam kütle merkezi tam sağ kenar hizasından geçtiği için sınırda kalır', 'Sola doğru net tork oluşacağı için sol kenar etrafında devrilir'], 'Sol alt köşeyi x = 0 alırsak küp merkezleri sırasıyla 0,5a, 1,0a, 1,5a ve 2,0a olur. Ortak x_km = (0,5 + 1,0 + 1,5 + 2,0)a / 4 = 5a / 4 = 1,25a > a olduğundan taban dışına çıkar ve sağa devrilir.'),
  ('Üçgen biçimindeki türdeş ince bir levhanın kenar ortaylarının kesişim noktası G\'dir. Levha herhangi bir kenar ortay doğrusu boyunca kesilerek iki parçaya ayrılırsa elde edilen bu iki üçgen parçanın kütleleriyle ilgili hangisi kesinlikle doğrudur?', 'Tabanları ve yükseklikleri eşit olduğundan iki parçanın kütleleri birbirine eşittir', ['Dar açılı köşeyi içeren parçanın kütlesi her zaman iki kat büyüktür', 'Yalnızca eşkenar üçgenlerde iki parçanın kütlesi birbirine eşit çıkar', 'Kesim çizgisi G\'den geçtiği için parçaların kütleleri 1\'e 2 oranındadır'], 'Kenar ortay karşı kenarı iki eşit parçaya böler; iki üçgenin tepe noktası ortak olduğundan yükseklikleri de eşittir. Eşit alanlı türdeş iki parçanın kütleleri eşittir.'),
  ('Yatay düzlemdeki eşkenar üçgenin üç köşesine m, m ve 4m kütleli üç küçük bilye yerleştirilmiştir. Eşkenar üçgenin bir kenarının yüksekliği h olduğuna göre sistemin kütle merkezi 4m kütleli bilyenin bulunduğu köşeden kaç h uzaktadır?', '4m kütleli köşeden h / 3 uzaktadır', ['4m kütleli köşeden 2h / 3 uzaktadır', '4m kütleli köşeden h / 2 uzaktadır', '4m kütleli köşeden h / 6 uzaktadır'], 'Diğer iki köşedeki m ve m kütlelerinin ortak merkezi karşı kenarın orta noktasındadır (toplam 2m, 4m köşesinden h kadar uzakta). 4m köşesine uzaklık: x = (2m · h) / (4m + 2m) = h/3 olur.'),
  ('Uzunluğu L olan türdeş düz bir tel bükülerek düzgün altıgen biçiminde kapalı bir çerçeve haline getiriliyor ve bir köşesinden iple tavana asılıyor. Denge durumunda altıgenin kenarlarından hangileri tam düşey doğrultuda durur?', 'Asılma köşesine komşu olmayan karşılıklı iki paralel kenar düşey durur', ['Altıgenin hiçbir kenarı düşey veya yatay doğrultuya gelemez', 'Asılma köşesinden çıkan iki kenardan yalnızca biri düşey durur', 'Altıgenin en alt ve en üstteki iki paralel kenarı yatay durur'], 'Düzgün altıgen bir köşesinden asıldığında ip uzantısı merkezden ve tam karşı köşeden geçer; bu köşegen doğrusuna paralel olan sağ ve sol yan kenarlar tam düşey konumda kalır.'),
  ('Desteğin yük ile kuvvet arasında bulunduğu çift taraflı (birinci tip) bir kaldıraç için \'her zaman kuvvetten kazanç vardır\' genellemesi neden yanlıştır?', 'Destek kuvvete daha yakın yerleştirilirse kuvvet kolu kısalır ve kuvvetten kayıp oluşur', ['Çift taraflı kaldıraçlarda sürtünme kuvveti her zaman kazancı sıfıra indirir', 'Destek ortada olduğunda kuvvetin yönü hiçbir zaman değiştirilemez', 'Bu tip kaldıraçlar yalnızca ağırlıksız cisimleri dengelemek için kullanılır'], 'Birinci tip kaldıraçta KK = d_kuvvet / d_yük oranıdır; destek yüke yakınsa KK > 1, tam ortadaysa KK = 1 (eşit kollu terazi), kuvvete yakınsa KK < 1 olur.'),
  ('Ofislerde kağıtları birbirine tutturmak için kullanılan tel zımba makinesinde kullanıcı üst gövdenin tam ortasından parmağıyla bastırdığında (arka uç menteşeli, ön uçta zımba teli kağıdı delmektedir) kuvvet kazancı ile ilgili ne söylenebilir?', 'Kuvvet kolu yük kolunun yarısı olduğundan kuvvet kazancı 1/2\'dir', ['Arka menteşe destek olduğundan kuvvet kazancı 2 değerindedir', 'Üstten dik basıldığı için kuvvet kazancı her zaman 1\'e eşittir', 'Zımba teli ince olduğu için kuvvet kazancı sonsuza yaklaşır'], 'Arka menteşe destek (0), parmak ortada (L/2), zımba teli uçta (L) olduğundan KK = (L/2) / L = 1/2 olur; ancak zımba telinin uç kesit alanı çok küçük olduğu için yüksek basınçla kağıdı deler.'),
  ('Yarıçapı r = 10 cm olan bir hareketli makaranın serbest ip ucu düşey yukarı doğru h = 120 cm çekildiğinde makara merkezine asılı yük kaç cm yükselir ve makara kendi ekseni etrafında kaç tam tur döner? (π = 3 alınız, ip makarada kaymamaktadır)', 'Yük 60 cm yükselir ve makara 1 tam tur döner', ['Yük 60 cm yükselir ve makara 2 tam tur döner', 'Yük 120 cm yükselir ve makara 2 tam tur döner', 'Yük 30 cm yükselir ve makara 1 tam tur döner'], 'Çekilen 120 cm ipin yarısı (60 cm) makarayı ve yükü yükseltmeye, diğer yarısı (60 cm) makarayı döndürmeye karşılık gelir. Makara çevresi 2πr = 2·3·10 = 60 cm olduğundan n = 60 / 60 = 1 tur döner.'),
  ('Ağırlığı 20 N olan bir hareketli makaranın altına 100 N ağırlığında yük asılmış ve ipin serbest ucu düşey yukarı çekilerek sistem sabit hızla yükseltilmektedir. İpteki gerilme kuvveti kaç N\'dur ve bu düzeneğin mekanik verimi yüzde kaçtır? (Sürtünmeler önemsizdir)', 'İp gerilmesi 60 N olup verim %83,3 (yani 5/6) değerindedir', ['İp gerilmesi 50 N olup verim %100 değerindedir', 'İp gerilmesi 60 N olup verim %80 (yani 4/5) değerindedir', 'İp gerilmesi 70 N olup verim %75 değerindedir'], 'İki ip kolu hem yükü hem makarayı taşır: 2F = 100 + 20 = 120 => F = 60 N. İp 2h çekildiğinde verim η = (P·h) / (F·2h) = 100 / 120 = 5/6 ≈ %83,3 bulunur.'),
  ('İki sabit ve iki hareketli makaradan oluşan klasik bir palanga sisteminde (toplam 4 makara, makara ağırlıkları ve sürtünmeler önemsiz), halatın başlangıç ucu üstteki sabit makara bloğunun kancasına bağlanmış ve serbest ucu aşağı doğru çekilmektedir. 240 N\'luk bir yükü dengeleyen kuvvet kaç N\'dur?', '60 N büyüklüğünde çekme kuvveti', ['48 N büyüklüğünde çekme kuvveti', '80 N büyüklüğünde çekme kuvveti', '120 N büyüklüğünde çekme kuvveti'], 'Halat sabit bloğa bağlanıp serbest uç aşağı çekildiğinde alttaki 2 hareketli makarayı yukarı taşıyan paralel ip kolu sayısı 4\'tür: 4F = 240 => F = 60 N.'),
  ('Yine 2 sabit ve 2 hareketli makaradan oluşan (toplam 4 ağırlıksız makaralı) bir palangada halatın başlangıç ucu bu kez alttaki hareketli makara bloğuna bağlanır ve serbest uç son hareketli makaradan çıkıp yukarı doğru çekilirse 300 N\'luk yükü dengeleyen F kuvveti kaç N olur?', '60 N büyüklüğünde yukarı yönlü kuvvet', ['75 N büyüklüğünde yukarı yönlü kuvvet', '50 N büyüklüğünde yukarı yönlü kuvvet', '100 N büyüklüğünde yukarı yönlü kuvvet'], 'Halat hareketli bloğa bağlanıp serbest uç da yukarı çekildiğinde hareketli bloğu taşıyan toplam paralel ip kolu sayısı 4 + 1 = 5 olur: 5F = 300 => F = 60 N bulunur.'),
  ('Ağırlığı 600 N olan bir dış cephe boyacısı, 200 N ağırlığındaki sepetin içindeyken tavandaki sabit makaradan geçen halatın diğer ucunu kendisi çekmek yerine halatı yerde duran arkadaşı çekerek sepeti dengede tutmaktadır. Yerdeki arkadaşının halata uyguladığı kuvvet ve boyacının sepet tabanına uyguladığı etki kuvveti kaçar N\'dur?', 'Arkadaşı 800 N çeker; boyacı sepet tabanına 600 N basar', ['Arkadaşı 400 N çeker; boyacı sepet tabanına 200 N basar', 'Arkadaşı 800 N çeker; boyacı sepet tabanına 200 N basar', 'Arkadaşı 600 N çeker; boyacı sepet tabanına 600 N basar'], 'Halatı dışarıdaki arkadaşı çektiğinde sepet+boyacı sistemini yalnızca tek bir halat kolu yukarı taşır: T = 600 + 200 = 800 N. Boyacı halata dokunmadığı için sepet tabanına kendi tam ağırlığı olan 600 N ile basar.'),
  ('Ağırlığı önemsiz bir hareketli makaradan geçen ipin iki kolu tam düşey paralel olmak yerine birbirleriyle 60° açı yapacak biçimde yukarıya doğru açılmıştır (her kol düşeyle 30° açı yapmaktadır). Makaraya asılı yük 60√3 N olduğuna göre ip gerilmesi kaç N\'dur? (cos30° = √3/2)', '60 N büyüklüğünde ip gerilmesi oluşur', ['30√3 N büyüklüğünde ip gerilmesi oluşur', '30 N büyüklüğünde ip gerilmesi oluşur', '60√3 N büyüklüğünde ip gerilmesi oluşur'], 'İki koldaki ip gerilmesi eşittir (F). Düşey bileşenlerin toplamı yükü dengeler: 2 · F · cos30° = 60√3 => 2 · F · (√3/2) = 60√3 => F = 60 N bulunur.'),
  ('Eşit kollu bir terazinin sol kefesine K cismi, sağ kefesine L cismi konulduğunda terazi yatay dengede kalmaktadır. Ancak bu terazinin kollarının aslında eşit olmadığı, sol kolun 20 cm, sağ kolun 25 cm olduğu sonradan fark ediliyor (boş kefeler kendi içinde dengelenmiştir). K cisminin kütlesi 500 gram olduğuna göre L cisminin gerçek kütlesi kaç gramdır?', 'L cisminin gerçek kütlesi 400 gramdır', ['L cisminin gerçek kütlesi 625 gramdır', 'L cisminin gerçek kütlesi 500 gramdır', 'L cisminin gerçek kütlesi 450 gramdır'], 'Destek noktasına göre tork eşitliğinden: m_K · 20 = m_L · 25 => 500 · 20 = m_L · 25 => 10000 = 25 · m_L => m_L = 400 gram bulunur.'),
  ('Ağırlığı 15 N olan her bir makaranın kullanıldığı 1 sabit ve 1 hareketli makaralı (serbest uç yukarı çekilen, yani yükü 2 ip kolunun taşıdığı) düzenekte 105 N ağırlığındaki çimento torbası sabit hızla 4 m yukarı çıkarılıyor. Kuvvetin yaptığı toplam iş kaç Joule olur? (Sürtünme önemsizdir)', '480 Joule iş yapılır', ['420 Joule iş yapılır', '540 Joule iş yapılır', '240 Joule iş yapılır'], 'Hareketli makara (15 N) da çimento torbasıyla (105 N) birlikte 4 m yükselir; sabit makara yükselmez. Sürtünmesiz ortamda yapılan toplam iş = (105 + 15) · 4 = 120 · 4 = 480 J (veya F = 60 N, x = 8 m => 60 · 8 = 480 J).'),
  ('Ağırlığı önemsiz eşit bölmeli bir çubukta destek bir uçtan 2 bölme uzaktadır. Bu uca 60 N ağırlığında bir yük asıldığında, çubuğun diğer ucuna dik olarak uygulanan 20 N\'luk kuvvet sistemi yatay dengede tutuyorsa çubuk toplam kaç bölmedir?', '8 bölme', ['6 bölme', '10 bölme', '12 bölme'], 'Desteğe göre tork dengesinden 60·2 = 20·x yazılır ve kuvvetin desteğe uzaklığı x = 6 bölme bulunur; toplam uzunluk 2 + 6 = 8 bölmedir.'),
  ('Kuvvet kazancının 4 olduğu sürtünmesiz ve ağırlıksız bir basit makine düzeneğinde, yükü düşeyde yarım metre yükseltmek için kuvvetin uygulandığı nokta kaç metre hareket ettirilmelidir?', '2 metre', ['4 metre', '1 metre', '8 metre'], 'İdeal basit makinelerde kuvvet kazancı yol kaybına eşittir; kazanç 4 ise kuvvetin aldığı yol yükün yükselmesinin 4 katı yani 0,5·4 = 2 metre olur.'),
  ('Sürtünmesiz bir eğik düzlemin uzunluğu yüksekliğinin 5 katıdır. Bu eğik düzlem üzerindeki 150 N ağırlığındaki bir sandığı eğik düzleme paralel bir kuvvetle sabit hızla yukarı çıkarmak için kaç N kuvvet gerekir?', '30 N', ['50 N', '75 N', '150 N'], 'Eğik düzlemde F·L = P·h bağıntısından F·5h = 150·h yazılır ve F = 30 N elde edilir.'),
  ('Sürtünmesiz bir eğik düzlemin eğim açısı artırıldığında (uzunluğu sabit kalacak şekilde daha dik hale getirildiğinde), aynı yükü sabit hızla tepeye çıkarmak için gereken paralel kuvvet ve yapılan toplam iş nasıl değişir?', 'Hem kuvvet hem de yapılan iş artar', ['Kuvvet artar fakat yapılan net iş değişmez', 'Kuvvet azalır ancak yapılan net iş artar', 'Hem kuvvet hem de yapılan net iş değişmez'], 'Uzunluk L sabitken açı artarsa yükseklik h = L·sin(alfa) artar; dolayısıyla hem F = P·sin(alfa) kuvveti hem de W = P·h işi artar.'),
  ('Makara ağırlıklarının ve sürtünmelerin önemsiz olduğu bir sistemde 3 adet hareketli makara, her birinin ipi bir üstteki hareketli makaraya bağlanacak şekilde kademeli (seri) kurgulanmıştır. En alttaki makaraya asılı yükü dengeleyen kuvvet yükün kaçta kaçıdır?', '1/8\'i', ['1/6\'sı', '1/3\'ü', '1/9\'u'], 'Kademeli bağlı n adet ağırlıksız hareketli makara sisteminde kuvvet kazancı 2^n formülüyle bulunur; n = 3 için kazanç 2^3 = 8 olduğundan kuvvet yükün 1/8\'idir.'),
  ('Ağırlıksız ve sürtünmesiz makaralardan oluşan bir palanga sisteminde bir sabit ve bir hareketli makara bulunmaktadır. İpin ucu hareketli makaradan başlayıp en son yukarı doğru çekilerek dengeleniyorsa, yükü 1 metre yükseltmek için ip kaç metre çekilmelidir?', '3 metre', ['2 metre', '4 metre', '1,5 metre'], 'İp hareketli makaraya bağlanıp yukarı doğru çekiliyorsa hareketli makarayı yukarı taşıyan 3 ip kolu vardır; kuvvet kazancı 3 olduğundan ip 3 metre çekilmelidir.'),
  ('Bir sabit makaranın üzerinden geçen ipin bir ucunda kütleli bir kova, diğer ucunda ise ipi çekerek kovayı sabit ivmeyle hızlandıran bir işçi vardır. Makara sürtünmesiz ancak kütlesi sıfırdan farklı (eylemsizlik momenti olan) bir disk ise iplerdeki gerilmeler için ne söylenebilir?', 'İşçinin çektiği taraftaki ip gerilmesi, kovaya bağlı taraftaki ip gerilmesinden büyüktür', ['Makara sabit olduğu için ipin her iki kolundaki gerilme kuvvetleri birbirine kesinlikle eşittir', 'Kovanın bağlı olduğu taraftaki ip gerilmesi, işçinin uyguladığı kuvvetten daha büyüktür', 'İp gerilmeleri yalnızca kovanın ağırlığına eşit olup ivmeden tamamen bağımsızdır'], 'Kütlesi olan makaranın açısal ivme kazanabilmesi için net tork gerekir; bu nedenle çekilen koldaki gerilme diğer koldan büyük olmalıdır.'),
  ('Ayak parmak uçlarında yükselen bir balerinin ayağı basit bir kaldıraç modeli olarak incelendiğinde; destek, yük ve kuvvetin konumları sırasıyla nasıl eşleşir?', 'Parmak uçları destek, vücut ağırlığı ortada yük, baldır kası aşil tendonuyla uçta kuvvettir', ['Topuk kemiği destek, parmak uçları yük, ayak bileği eklemi ortada kuvvettir', 'Ayak bileği ortada destek, topuk kemiği yük, parmak uçları uçta kuvvettir', 'Vücut ağırlığı uçta destek, aşil tendonu ortada kuvvet, parmak uçları yüktür'], 'Parmak ucu yere basarak dönme ekseni (destek) olur; tibia üzerinden inen vücut ağırlığı ortada yük, topuğa bağlanan aşil tendonu uçta yukarı yönlü kuvvettir.'),
  ('Ağırlığı önemsiz bir kaldıraçta yük kolu 40 cm, kuvvet kolu ise 160 cm\'dir. Yük ucuna 240 N ağırlığında bir taş konulduğunda sistemi yatay dengede tutacak minimum kuvvet kaç N\'dur?', '60 N', ['80 N', '40 N', '120 N'], 'Minimum kuvvet çubuğa dik uygulanan kuvvettir: F·160 = 240·40 eşitliğinden F = 60 N bulunur.'),
  ('Sürtünmesiz bir hareketli makaranın merkezine 50 N\'luk bir yük asılmıştır. Makaranın etrafından geçen ipin bir ucu tavana düşey sabitlenmiş, diğer ucu ise düşeyle 60 derece açı yapacak şekilde eğik çekilmeye çalışılmaktadır. Yalnızca düşey ip ve eğik ip bulunan bu durumda ne gözlenir?', 'Eğik ipteki yatay kuvvet bileşeni dengelenemediği için makara yatayda kayar ve sol kol da açılı hale gelir', ['İpteki gerilme kuvveti düşey çekilme durumuna göre yarı yarıya azalarak sabit kalır', 'Makaranın ağırlığı sıfır olduğundan sol kol tam düşey kalmaya devam eder', 'Tavana bağlı ip kolundaki gerilme, çekilen uçtaki gerilmenin tam iki katına çıkar'], 'Aynı ipteki gerilme her yerde eşit (F) olduğundan bir kol düşey kalırken diğeri açılı çekilirse F·sin60 net yatay kuvveti makarayı yana çeker ve denge iki kolun düşeyle eşit açı yaptığı konumda kurulur.'),
  ('Ağırlığı önemsiz bir hareketli makaranın etrafından geçen ipin bir ucu tavana bağlı, diğer ucu ise yukarı doğru 35 N\'luk kuvvetle çekilmektedir. Makaraya asılı yük 50 N ise (g = 10 m/s^2), yükün yukarı yönlü ivmesi kaç m/s^2 olur?', '4 m/s^2', ['2 m/s^2', '5 m/s^2', '3,5 m/s^2'], 'Makarayı yukarı çeken net kuvvet 2·35 = 70 N, aşağı çeken yük 50 N\'dur (kütlesi m = 5 kg). F_net = 70 - 50 = 20 N; a = 20 / 5 = 4 m/s^2 bulunur.'),
  ('Dağlık bölgelerde kara yollarının doğrudan zirveye tırmanmak yerine virajlar (zikzaklar) çizerek yapılması fizikteki hangi ilkeyle açıklanır?', 'Yüksekliği sabit tutarken yolun uzunluğunu artırarak eğimi azaltmak ve araç motorunun ihtiyaç duyduğu çekiş kuvvetini düşürmek', ['Aracın zirveye çıktığında kazanacağı toplam kütleçekim potansiyel enerjisini azaltarak yakıt tasarrufu sağlamak', 'Lastikler ile asfalt arasındaki sürtünme katsayısını sıfıra indirerek tekerleklerin dönme direncini yok etmek', 'Aracın ağırlık merkezini yerin merkezine yaklaştırarak yerçekimi ivmesinin şiddetini yarıya düşürmek'], 'Virajlı dağ yolları eğik düzlem örneğidir; L yolunu uzatarak gerekli F çekiş kuvvetini küçültür.'),
  ('Sürtünmesiz bir palanga düzeneğinde 2 sabit ve 2 hareketli makara kullanılmıştır. Makaraların her birinin ağırlığı önemsiz olup ip yukarıdan aşağıya doğru çekilmektedir. 360 N ağırlığındaki bir yükü sabit hızla kaldırmak için uygulanması gereken kuvvet kaç N\'dur?', '90 N', ['72 N', '120 N', '60 N'], 'Toplam 4 makaralı klasik palangada ip aşağı çekildiğinde hareketli makaraları taşıyan ip kolu sayısı 4\'tür; F = 360 / 4 = 90 N.'),
  ('Bir sabit makaranın etrafından geçirilen ipin bir ucunda 40 N ağırlığında bir cisim asılıdır, diğer ucu ise yerdeki bir halkaya düşey olarak bağlanmıştır. Makara ağırlığı 8 N olduğuna göre, sabit makarayı tavana bağlayan zincirdeki gerilme kuvveti kaç N\'dur?', '88 N', ['48 N', '80 N', '96 N'], 'İpin bir ucunda 40 N cisim dengedeyse ipin her noktasında gerilme 40 N\'dur. Sabit makarayı aşağı çeken iki paralel ip kolu (40 + 40 = 80 N) ve kendi ağırlığı (8 N) vardır; toplam 88 N olur.'),
  ('Uzunluğu 10 metre, yüksekliği 2 metre olan sürtünmesiz bir eğik düzlemin tepesindeki sabit makaradan geçen ipin bir ucu eğik düzlem üzerindeki 200 N ağırlığındaki arabaya, diğer ucu ise boşlukta sarkan K cismine bağlıdır. Sistem dengede olduğuna göre K cisminin ağırlığı kaç N\'dur?', '40 N', ['50 N', '100 N', '20 N'], 'Eğik düzlemdeki arabanın ipe uyguladığı çekme kuvveti P·(h/L) = 200·(2/10) = 40 N\'dur; sarkan K cismi doğrudan bu ip gerilmesine eşit olduğundan ağırlığı 40 N\'dur.'),
  ('Her birinin ağırlığı 6 N olan iki hareketli makara alt alta kademeli (alt makaranın çekme ipi üst hareketli makaranın kancasına bağlı, diğer uçları tavana sabit) olarak kurulmuştur. Alt makaraya 54 N yük asıldığında en üstteki serbest ipi yukarı çeken dengeleyici kuvvet kaç N\'dur?', '18 N', ['15 N', '16,5 N', '13,5 N'], 'Alt makarada 2·T = 54 + 6 = 60 N olup T = 30 N bulunur; üst makarada ise 2·F = 30 + 6 = 36 N eşitliğinden F = 18 N elde edilir.'),
  ('Ağırlıkları 10\'ar N olan 1 sabit ve 1 hareketli makaradan oluşan sürtünmesiz bir düzenekte, ip sabit makaradan başlayıp hareketli makaranın altından geçerek yukarı doğru çekilmektedir. Hareketli makaraya 70 N yük asıldığında sistemin kuvvet kazancı kaç olur?', '1,75', ['2,00', '1,40', '3,50'], 'Hareketli makarayı yukarı çeken 2 ip kolu vardır: 2F = 70 + 10 = 80 N -> F = 40 N. Kuvvet kazancı P / F = 70 / 40 = 1,75\'tir.'),
  ('Eşit kollu bir terazinin sol kefesine bir cisim, sağ kefesine ise dengeleyici kütleler konularak yatay denge sağlanmıştır. Bu terazi düzeneği Dünya yerine yerçekimi ivmesinin daha küçük olduğu Ay yüzeyine götürülürse denge durumu nasıl etkilenir?', 'Her iki kefedeki ağırlıklar aynı oranda azalacağı için yatay denge bozulmaz', ['Sağ kefedeki standart kütleler daha fazla hafifleyeceği için sol kefe aşağı iner', 'Yerçekimi ivmesi azaldığı için terazinin destek noktası üzerindeki tork sıfırlanır ve kol dikleşir', 'Kuvvet kazancı altıda birine düşeceği için dengeyi sağlamak adına sağ kefeye ek kütle gerekir'], 'Tork eşitliği m1·g·d = m2·g·d olduğundan g ivmesi sadeleşir (g > 0 iken) ve denge değişmez.'),
  ('Bir ceviz kıracağının kollarının uzunluğu menteşeden itibaren 18 cm\'dir. Menteşeye 3 cm uzaklığa yerleştirilen sert bir cevizin kabuğu en az 300 N\'luk sıkıştırma kuvvetiyle kırılabilmektedir. Cevizi kırmak için kolların uçlarına dik olarak uygulanması gereken minimum kuvvet kaç N\'dur?', '50 N', ['60 N', '45 N', '75 N'], 'Menteşeye göre tork eşitliğinden F·18 = 300·3 yazılır; 18F = 900 buradan F = 50 N bulunur.'),
  ('Ağırlığı G olan 6 bölmeli türdeş bir çubuğun sol ucuna bir hareketli makaranın gövdesi, sağ ucuna ise bu makaradan çıkıp tavandaki sabit makaradan dolanan aynı ipin ucu düşey olarak bağlanmıştır (makaralar ağırlıksız ve sürtünmesiz, hareketli makaranın diğer ip ucu tavana bağlıdır). Çubuğun sol uçtan kaç bölme uzağına G ağırlığında ek bir yük asılırsa çubuk yatay dengede kalır?', '1 bölme', ['2 bölme', '1,5 bölme', '2,5 bölme'], 'Sağ uçta yukarı T, sol uçta yukarı 2T vardır; düşey dengeden 3T = 2G -> T = 2G/3. Sol uca göre tork alınırsa G(çubuk)·3 + G(yük)·x = T·6 -> 3G + Gx = 4G -> x = 1 bölme bulunur.'),
  ('Yüksekliği 1,5 metre olan bir kamyon kasasına 240 N ağırlığındaki bir buzdolabını yüklemek için 4,5 metre uzunluğunda sürtünmesiz bir kalas kullanılıyor. Buzdolabını kalasa paralel kuvvetle sabit hızla kasaya iterken uygulanan kuvvet kaç N ve yapılan iş kaç Joule\'dür?', '80 N kuvvet uygulanır, 360 Joule iş yapılır', ['80 N kuvvet uygulanır, 1080 Joule iş yapılır', '120 N kuvvet uygulanır, 360 Joule iş yapılır', '60 N kuvvet uygulanır, 540 Joule iş yapılır'], 'Kuvvet F = P·(h/L) = 240·(1,5 / 4,5) = 80 N\'dur. Yapılan iş W = P·h = 240·1,5 = 360 Joule olur.'),
  ('Bir palanga sisteminde makara sayısını değiştirmeden sadece ipin bağlanma şekli değiştirilerek çekilen son ipin yönü aşağıdan yukarıya çevriliyor (makaralar ağırlıksız ve sürtünmesiz). Bu değişiklik sonucunda aşağıdakilerden hangisi gerçekleşir?', 'Kuvvet kazancı 1 artar, ancak yükü aynı yüksekliğe çıkarmak için çekilmesi gereken ip uzunluğu da artar', ['Kuvvet kazancı değişmez, yalnızca işçinin ipi çekme kolaylığı artmış olur', 'Yükü kaldırmak için gereken kuvvet büyür fakat yapılan net iş azalır', 'Makaraları tavana bağlayan zincirdeki gerilme kuvveti iki katına çıkar'], 'Ağırlıksız palangada ip yukarı çekildiğinde yükü taşıyan ip kolu sayısı 1 artar (n yerine n+1 olur), dolayısıyla kuvvet azalır ve çekilen ip miktarı artar.'),
  ('Toplam 6 bölmeli, ağırlığı önemsiz bir çubuk tam ortasından (3. bölmeden) desteklenmiştir. Sol uca X cismi, sağ tarafta ise desteğe 1 bölme uzaklığa Y cismi asıldığında yatay denge sağlanıyor. X ve Y cisimlerinin asılı oldukları noktalar birbiriyle değiştirilirse, çubuğun tekrar yatay dengede kalması için sağ uca kaç X ağırlığında ek bir cisim asılmalıdır?', '8/3 X', ['6 X', '3 X', '9/2 X'], 'İlk durumda X·3 = Y·1 -> Y = 3X\'tir. Yerleri değiştiğinde sol uçta Y (torku 3X·3 = 9X), sağda desteğe 1 bölmede X (torku X·1 = X) bulunur. Sağ uca (desteğe 3 bölme) K cismi asılırsa: 9X = X + K·3 -> K = 8/3 X olur.'),
  ('Sürtünmesiz iki eğik düzlem tabanları zeminde, tepeleri ortak olacak şekilde sırt sırta yerleştirilmiştir. Sol eğik düzlemin uzunluğu 6 m, sağ eğik düzlemin uzunluğu ise 4 m\'dir. Tepedeki ağırlıksız sabit makaradan geçen iple sol yüzeydeki 90 N ağırlığındaki cisim ile sağ yüzeydeki P ağırlıklı cisim dengede olduğuna göre P kaç N\'dur?', '60 N', ['135 N', '45 N', '80 N'], 'Ortak yükseklik h olduğundan ip gerilmesi T = 90·(h/6) = P·(h/4) eşitliğini sağlar; h\'lar sadeleşir ve 15 = P/4 buradan P = 60 N bulunur.'),
  ('Sürtünmelerin önemsenmediği bir ortamda bir yükü aynı yüksekliğe çıkarmak için ayrı ayrı sabit makara, hareketli makara ve eğik düzlem kullanılıyor (makaralar ağırlıksız). Bu üç düzenek için hangi fiziksel nicelik kesinlikle ortaktır?', 'Yükün kazandığı kütleçekim potansiyel enerjisi', ['Uygulanan dengeleyici kuvvetlerin büyüklüğü', 'Kuvvetlerin uygulandığı noktaların yer değiştirme miktarı', 'Düzeneklerin sağladığı mekanik avantaj oranı'], 'Yük aynı ve çıkılan yükseklik h aynı olduğundan yükün kazandığı potansiyel enerji (P·h) üçünde de birbirine eşittir.'),
  ('Önkol kemiğimiz dirsek eklemi etrafında dönerken, pazu (biseps) kası dirseğe oldukça yakın bir noktadan kemiğe bağlanır ve elimizdeki bir dambılı yukarı kaldırır. Bu biyomekanik kaldıraç sistemiyle ilgili hangi çıkarım doğrudur?', 'Pazu kasının ürettiği gerilme kuvveti dambılın ağırlığından çok daha büyüktür, buna karşılık kas az miktarda kasıldığında el geniş bir yay çizer', ['Dirsek eklemi el ile kas arasında yer aldığı için pazu kası dambıl ağırlığının onda biri kadar kuvvetle denge kurar', 'Dambıl dirsek ile pazu kasının bağlanma noktası arasında bulunduğundan sistemde kuvvet kazancı birden büyüktür', 'El bileğindeki hareket miktarı pazu kasının kısalma miktarından daha az olduğu için enerjiden kazanç sağlanır'], 'Önkol kuvvetin ortada (dirseğe çok yakın) olduğu 3. tip kaldıraçtır; kas büyük kuvvet üretir fakat küçük kasılmayla elin hızlı ve geniş hareket etmesini sağlar.'),
  ('Ağırlığı önemsiz 10 bölmeli bir çubuk, sol uçtan 3 bölme uzağa konulan bir destek üzerinde yatay dengededir. Sol uca 40 N\'luk bir yük, çubuğun 7. bölmesine ise 65 N\'luk bir yük asılmıştır. Çubuğun sağ ucuna (10. bölmeye) tavandaki sabit makaradan geçen bir ip düşey bağlanıp ipin diğer ucuna K cismi sarkıtıldığına göre K cisminin ağırlığı kaç N\'dur?', '20 N', ['30 N', '25 N', '15 N'], '3. bölmedeki desteğe göre sol uçtaki 40 N saat yönünün tersine (40·3 = 120), sağ uçtaki ip yukarı çekerek yine saat yönünün tersine (K·7) tork üretir; 7. bölmedeki 65 N ise saat yönünde (65·4 = 260) tork üretir: 120 + 7K = 260 -> K = 20 N.'),
  ('Aynı maddeden yapılmış türdeş ve düzgün kesitli dikdörtgen bir demir levha, bir kenarından menteşelenerek düşey duvara tutturulmuş ve karşı kenarından düşey yukarı bir F kuvvetiyle yatayda dengelenmiştir. Levhanın menteşeye dik boyu iki katına çıkarılıp kalınlığı yarıya indirilirse (genişlik sabit), yatay dengeyi sağlayan F kuvveti nasıl değişir?', 'Değişmez', ['İki katına çıkar', 'Yarıya iner', 'Dört katına çıkar'], 'Boy 2 katına çıkıp kalınlık yarıya inerse levhanın hacmi ve ağırlığı (G) değişmez. Türdeş levhanın ağırlık merkezi her iki durumda da boyun tam ortasındadır (G·(L/2) = F·L -> F = G/2); F değişmez.'),
  ('Sürtünmesiz bir sistemde bir ucu tavana bağlı ip, aşağıda bir hareketli makaradan geçip yukarıda bir sabit makaradan dolanmakta ve bu ipin ucuna 45 N ağırlığında X cismi asılmaktadır. Hareketli makaranın kancasına asılı Y cismi sistemi dengede tutuyor ve hareketli makaranın kendi ağırlığı 10 N ise Y cisminin ağırlığı kaç N\'dur?', '80 N', ['90 N', '100 N', '70 N'], 'Sabit makaradan sarkan X cismi 45 N olduğundan ipteki gerilme her yerde 45 N\'dur. Hareketli makarayı yukarı çeken 2·45 = 90 N\'dur; 10 N makara ağırlığı çıkarılırsa Y = 90 - 10 = 80 N bulunur.'),
  ('Yatay düzlemle alfa açısı yapan sürtünmesiz bir eğik düzlemin alt ucundan eğik düzleme paralel v0 hızıyla fırlatılan bir cisim en fazla L kadar yol alıp geri dönüyor. Aynı eğik düzlemin eğim açısı artırılarak sin(alfa) değeri iki katına çıkarılır ve cisim aynı v0 hızıyla fırlatılırsa eğik düzlem üzerinde çıkabileceği maksimum yol kaç L olur?', 'L / 2', ['L / 4', 'L', '2L'], 'Enerji korunumundan (1/2)mv0^2 = mg·L·sin(alfa) yazılır. İlk kinetik enerji sabitken sin(alfa) iki katına çıkarsa gidilen L yolu yarıya iner (L/2 olur).'),
  ('Sürtünmesiz bir eğik düzlemde 80 N ağırlığındaki bir cisim, eğik düzleme paralel bir ip yardımıyla sabit makaradan geçirilerek ağırlıksız bir hareketli makaranın merkezine bağlanmıştır. Hareketli makaranın etrafından geçen ipin bir ucu yerde sabit, diğer ucunda ise düşey yukarı çekilen 15 N\'luk kuvvet sistemi dengede tutuyorsa eğik düzlemin kuvvet kazancı kaçtır?', '8 / 3', ['16 / 3', '4', '8 / 5'], 'Hareketli makaranın merkezine bağlı ipin gerilmesi 2·15 = 30 N olur (eğer ipler aşağı/yukarı uyumluysa: durun, hareketli makaranın merkezini eğik düzlemdeki cisim yukarı çekiyorsa ve diğer iki ip aşağı doğruysa T_merkez = 2·15 = 30 N\'dur!). Eğik düzlemdeki cismi tutan ip 30 N ise kuvvet kazancı P / T = 80 / 30 = 8/3 bulunur.'),
  ('Sürtünmeli bir eğik düzlemde durmakta olan bir sandığı sabit hızla yukarı çıkarmak için eğik düzleme paralel 70 N kuvvet gerekirken, aynı sandık serbest bırakıldığında sabit hızla kendiliğinden aşağı kaymamakta, ancak eğik düzleme paralel aşağı yönde 10 N itildiğinde sabit hızla aşağı inmektedir. Buna göre sandığın ağırlığının eğik düzleme paralel bileşeni kaç N\'dur?', '30 N', ['40 N', '35 N', '20 N'], 'Yukarı çekerken F_yukarı = P_paralel + fs = 70 N. Aşağı sabit hızla inerken hareket aşağı yönlü olduğundan sürtünme yukarı yönlüdür: P_paralel + 10 = fs. İkinci ifadeyi birincide yerine yazarsak P_paralel + (P_paralel + 10) = 70 -> 2·P_paralel = 60 -> P_paralel = 30 N (fs = 40 N) bulunur.'),
  ('Bir makasla çok sert bir teneke levhayı kesen usta, tenekeyi makasın uç kısmına değil de birleşim vidasına (desteğe) olabildiğince yakın kısmına yerleştirir. Ustanın bu davranışı aşağıdakilerden hangisini amaçlar?', 'Yük kolunu kısaltarak tenekeye aktarılan kesme kuvvetini büyütmeyi', ['Kuvvet kolunu kısaltarak parmakların aldığı yolu azaltmayı', 'Yoldan kazanç oranını artırarak tenekeyi tek hamlede hızlıca kesmeyi', 'Makasın yaptığı net işi artırarak enerji korunumunu aşmayı'], 'Tenekeyi vidaya (desteğe) yaklaştırmak yük kolunu küçültür; aynı el kuvvetiyle tenekeye çok daha büyük bir kesme kuvveti uygulanır.'),
  ('Sürtünmesiz bir su kuyusu çıkrığında halatın sarıldığı silindirin yarıçapı 10 cm, çevirme kolunun uzunluğu ise 40 cm\'dir. Kuyudan 180 N ağırlığındaki dolu su kovasını sabit hızla çekmek için kola dik olarak uygulanması gereken kuvvet kaç N\'dur?', '45 N', ['60 N', '30 N', '90 N'], 'Çıkrıkta dönme eksenine göre tork dengesinden F·R = P·r yazılır: F·40 = 180·10 eşitliğinden F = 45 N bulunur.'),
  ('İpin sarıldığı silindir yarıçapı 5 cm, çevirme kolu uzunluğu 25 cm olan bir çıkrık kolu 4 tam tur döndürüldüğünde, silindire bağlı yük düşeyde kaç cm yer değiştirir? (pi = 3 alınız.)', '120 cm', ['600 cm', '60 cm', '240 cm'], 'Yükün yükselme miktarı çevirme kolunun uzunluğuna (R) bağlı değildir; yalnızca iç silindirin çevresi ile tur sayısının çarpımına eşittir: h = n·2·pi·r = 4·2·3·5 = 120 cm.'),
  ('Bir marangoz tahta bloğa vidaladığı bir vidayı tornavidayla 6 tam tur çevirdiğinde vidanın ucu tahta içinde 18 milimetre ilerliyor. Marangoz aynı vidayı sapı iki kat daha kalın başka bir tornavidayla 6 tam tur çevirseydi vida tahta içinde kaç milimetre ilerlerdi?', '18 milimetre', ['36 milimetre', '9 milimetre', '72 milimetre'], 'Vidanın ilerleme miktarı h = n·a bağıntısıyla bulunur; tornavida sapının kalınlığı yalnızca uygulanan kuvveti etkiler, ilerleme miktarı yine 18 mm olur.'),
  ('Vida adımı 2 mm olan bir vidayı sert bir ahşap zemine vidalamak için 14 cm uzunluğundaki bir anahtarın ucuna dik olarak 30 N kuvvet uygulanmaktadır. Ahşap zeminin vidanın ilerlemesine karşı gösterdiği direnç kuvveti (sürtünmesiz ideal kabulle) kaç N\'dur? (pi = 3 alınız.)', '12600 N', ['6300 N', '4200 N', '8400 N'], 'Vidada iş prensibinden F·2·pi·b = R_direnç·a yazılır. b = 14 cm = 140 mm alındığında: 30·2·3·140 = R_direnç·2 -> 30·420 = 12600 N bulunur.'),
  ('Otomobillerin lastiklerini değiştirirken aracı yukarı kaldırmak için kullanılan mekanik kriko sistemlerinde vida adımı oldukça küçük seçilir. Bunun temel fiziksel gerekçesi aşağıdakilerden hangisidir?', 'Kuvvet kazancını çok yüksek tutarak küçük bir kol kuvvetiyle tonlarca ağırlıktaki aracı kaldırabilmek', ['Kolun tek bir tur çevrilmesiyle aracı yarım metre yukarı kaldırarak zamandan tasarruf sağlamak', 'Aracın yerçekimi potansiyel enerjisindeki artışı sıfıra indirerek işten kazanç elde etmek', 'Vida dişleri arasındaki sürtünmeyi tamamen yok ederek krikonun kendi kendine boşalmasını sağlamak'], 'Vidada kuvvet kazancı 2·pi·b / a oranına bağlıdır; a vida adımı ne kadar küçükse mekanik avantaj o kadar büyük olur.'),
  ('Birbirine dıştan kenetlenmiş iki dişli çarktan K dişlisinin diş sayısı 48, L dişlisinin diş sayısı ise 16\'dır. K dişlisi ok yönünde 2 tam tur döndürüldüğünde L dişlisi hangi yönde kaç tur döner?', 'Ok yönünün tersine 6 tur', ['Ok yönünde 6 tur', 'Ok yönünün tersine 2/3 tur', 'Ok yönünde 3 tur'], 'Dişli çarklarda tur sayısı diş sayısıyla ters orantılıdır: nK·zK = nL·zL -> 2·48 = nL·16 -> nL = 6 tur; dıştan temas ettikleri için zıt yönde döner.'),
  ('Merkezleri farklı iki kasnağa düz (paralel) bağlanmış bir kayış ile çapraz bağlanmış bir kayış arasındaki temel fark aşağıdakilerden hangisidir?', 'Düz bağlamada kasnaklar aynı yönde dönerken, çapraz bağlamada kasnaklar zıt yönlerde döner', ['Çapraz bağlamada küçük kasnağın tur sayısı yarıya inerken, düz bağlamada iki katına çıkar', 'Düz bağlamada kayış üzerindeki çizgisel sürat her noktada farklıyken, çapraz bağlamada sabittir', 'Çapraz bağlama yalnızca yarıçapları eşit olan kasnaklar arasında hareket aktarımı yapabilir'], 'Düz kayış kasnakları aynı yönde, çapraz kayış ise dönme yönünü ters çevirerek zıt yönde döndürür; tur oranı değişmez.'),
  ('Yarıçapları sırasıyla 3r, r ve 2r olan X, Y ve Z dişlileri sırasıyla birbirine dıştan temas edecek şekilde yan yana dizilmiştir. X dişlisi saat yönünde 4 tur döndürülürse Z dişlisi hangi yönde kaç tur döner?', 'Saat yönünde 6 tur', ['Saat yönünün tersine 6 tur', 'Saat yönünde 12 tur', 'Saat yönünün tersine 8/3 tur'], 'Aradaki Y dişlisi (avara dişli) tur sayısı hesabında sadeleşir: nX·3r = nZ·2r -> 4·3 = nZ·2 -> nZ = 6 tur. X saat yönü -> Y tersi -> Z tekrar saat yönü olur.'),
  ('Bir bisikletin pedalının bağlı olduğu ön dişli çark (aynakol) ile arka tekerleğin göbeğindeki küçük dişli (ruble) bir zincirle birbirine bağlıdır. Yokuş yukarı çıkarken vitesi küçülterek zinciri arkadaki daha büyük yarıçaplı bir dişliye geçiren sürücü ne elde eder?', 'Pedala uygulaması gereken kuvveti azaltarak kuvvet kazancını artırır, fakat her pedal turunda bisiklet daha az yol alır', ['Pedalın bir tam turunda arka tekerleğin dönme sayısını artırarak bisikletin yokuşu daha yüksek süratle çıkmasını sağlar', 'Birim zamanda harcadığı biyolojik enerjiyi tamamen sıfırlayarak yerçekimine karşı yapılan işi yarıya düşürür', 'Zincir üzerindeki gerilme kuvvetini ön dişlide sıfırlayıp arka dişlide dört katına çıkararak torku yok eder'], 'Arka dişli büyüdüğünde ön/arka tur oranı küçülür; tekerlek daha az döner ancak arka tekerleğe aktarılan döndürme momenti artar ve pedal yumuşar.'),
  ('Bir eğik düzlemde 200 N ağırlığındaki bir sandığı 3 metre yüksekliğindeki platforma çıkarmak için 5 metre uzunluğundaki rampa boyunca sandığa paralel 150 N\'luk sabit kuvvet uygulanmaktadır. Bu eğik düzlem sisteminin verimi yüzde kaçtır?', '%80', ['%75', '%60', '%90'], 'Yararlı iş W_yük = P·h = 200·3 = 600 Joule. Kuvvetin yaptığı toplam iş W_kuvvet = F·L = 150·5 = 750 Joule. Verim = (600 / 750)·100 = %80 bulunur.'),
  ('Sürtünmelerin ihmal edildiği ancak hareketli makara ağırlığının önemsendiği bir düzenekte, tek bir hareketli makara yardımıyla 90 N ağırlığındaki yük sabit hızla yükseltilirken ipe 60 N kuvvet uygulanmaktadır. Bu sistemin verimi yüzde kaçtır?', '%75', ['%80', '%60', '%50'], 'Yük h kadar yükseldiğinde ip 2h çekilir. Yararlı iş = 90·h, yapılan toplam iş = 60·2h = 120·h olur. Verim = (90h / 120h)·100 = %75\'tir (hareketli makara ağırlığı 30 N\'dur).'),
  ('Bir dişli çark düzeneğinde çarkların arasına makine yağı damlatıldığında sistemin aşağıdaki özelliklerinden hangisinin artması beklenir?', 'Mekanik veriminin', ['Yoldan kazanç oranının', 'Dişlilerin tur sayısı oranının', 'İdeal kuvvet kazancı değerinin'], 'Yağlama sürtünme kayıplarını azaltır; tur oranı değişmez ancak ısıya dönüşen enerji azaldığı için verim artar.'),
  ('Merkezleri çakışık ve birbirine perçinli r ve 2r yarıçaplı iki dişliden büyük olanı düşey sabit bir kremayer (düz dişli ray) üzerinde kaymadan dönerek yükselmektedir. Bu eş merkezli dişli çifti kendi etrafında 3 tam tur döndüğünde dişli çiftinin kütle merkezi düşeyde kaç pi·r yükselir?', '12·pi·r', ['6·pi·r', '18·pi·r', '9·pi·r'], 'Kremayer raya temas eden dişli 2r yarıçaplı olan büyük dişlidir; kaymadan 3 tur döndüğünde merkez h = 3 · (2·pi·2r) = 12·pi·r yükselir.'),
  ('Dört eşit bölmeye ayrılmış daire biçimli bir K kasnağı ile yine dört eşit bölmeye ayrılmış, K\'nın 2 katı yarıçapa sahip L kasnağı çapraz bir kayışla birbirine bağlanmıştır. K kasnağının sağ üst çeyreği taralı iken K kasnağı saat yönünde 3/2 (bir buçuk) tur döndürülürse L kasnağı hangi yönde kaç tur döner?', 'Saat yönünün tersine 3/4 tur', ['Saat yönünde 3/4 tur', 'Saat yönünün tersine 3 tur', 'Saat yönünde 3/2 tur'], 'Çapraz bağlamada dönme yönü zıttır (saat yönünün tersi). Tur sayısı yarıçapla ters orantılıdır: (3/2)·r = nL·2r -> nL = 3/4 tur bulunur.'),
  ('Bir çıkrık düzeneğinde kuyudan çekilen kovanın ağırlığı iki katına çıkarıldığında, kovayı yine sabit hızla çekebilmek için çıkrık koluna uygulanan kuvvet ve kolun bir turunda yapılan iş nasıl değişir? (Sürtünmeler önemsizdir.)', 'Hem uygulanan kuvvet hem de bir turda yapılan iş iki katına çıkar', ['Kuvvet iki katına çıkar ancak bir turda yapılan iş sabit kalır', 'Kuvvet dört katına çıkar, bir turda yapılan iş iki katına çıkar', 'Kuvvet değişmez, yalnızca çıkrık kolunun dönme süresi iki katına çıkar'], 'P iki katına çıkınca F = P·(r/R) de iki katına çıkar; bir turda yükselme h = 2·pi·r sabit olduğundan W = P·h işi de iki katına çıkar.'),
  ('Vida adımı 3 mm olan bir mengene vidasının çevirme kolu uzunluğu 15 cm\'dir. Mengenenin çeneleri arasına sıkıştırılan metal parçaya 9000 N büyüklüğünde sıkıştırma kuvveti uygulayabilmek için çevirme kolunun ucuna dik olarak en az kaç N kuvvet uygulanmalıdır? (pi = 3, sürtünmeler önemsiz.)', '30 N', ['45 N', '15 N', '60 N'], 'F · 2·pi·R = N_sıkıştırma · a bağıntısında R = 15 cm = 150 mm yazılır: F · 2 · 3 · 150 = 9000 · 3 -> 900·F = 27000 -> F = 30 N bulunur.'),
  ('Ağırlıkları önemsiz bir çıkrık ile bir kaldıraç birleştirilmiştir: Yarıçapı r olan çıkrık silindirine sarılı ip, eşit bölmeli ağırlıksız 4 bölmeli bir kaldıracın sağ ucuna düşey bağlanmıştır; kaldıracın sol ucu menteşeli (destek) olup tam ortasına (2. bölmeye) 120 N\'luk bir yük asılmıştır. Çıkrık kolunun uzunluğu 3r olduğuna göre sistemi dengede tutan çıkrık kolu kuvveti kaç N\'dur?', '20 N', ['30 N', '40 N', '15 N'], 'Kaldıraçta sol uç desteğe göre: 120·2 = T·4 -> çıkrığa giden ip gerilmesi T = 60 N olur. Çıkrıkta ise F·3r = T·r = 60·r eşitliğinden F = 20 N bulunur.'),
  ('Bir bisiklette arka tekerleğin yarıçapı, arka dişli çarkın (rublenin) yarıçapından çok daha büyüktür ve bu ikisi eş merkezli olarak birlikte döner. Sadece arka dişli ile arka tekerlek arasındaki bu eş merkezli ilişki tek başına düşünüldüğünde hangi sonuç doğrudur?', 'Zincirin arka dişliye uyguladığı kuvvet, tekerleğin yere uyguladığı itme kuvvetinden büyüktür; yani bu ikili yoldan kazanç sağlar', ['Arka tekerlek arka dişliden daha fazla tur atarak bisikletin enerjisini iki katına çıkarır', 'Tekerlek yarıçapı büyük olduğu için bu eş merkezli ikili kuvvetten kazanç, yoldan kayıp üretir', 'Arka dişli ile arka tekerlek zıt yönlerde dönerek bisikletin dengede kalmasını sağlar'], 'Kuvvet içteki küçük dişliye (r) zincirle uygulanır, çıkış ise dıştaki büyük tekerlek çemberindedir (R); kuvvet içeriden uygulandığı için kuvvetten kayıp, yoldan (hızdan) kazanç vardır.'),
  ('Birbirine düz kayışla bağlı X ve Y kasnaklarından X\'in yarıçapı 20 cm, Y\'nin yarıçapı 50 cm\'dir. Y kasnağı ile eş merkezli olarak perçinlenmiş Z kasnağının yarıçapı ise 15 cm\'dir. X kasnağının kenarındaki bir noktanın çizgisel sürati 10 m/s olduğuna göre Z kasnağının kenarındaki bir noktanın çizgisel sürati kaç m/s\'dir?', '3 m/s', ['10 m/s', '4 m/s', '25 m/s'], 'Kayışla bağlı X ve Y\'nin kenar çizgisel süratleri eşittir: vY = vX = 10 m/s. Eş merkezli Y ve Z\'nin açısal hızları eşittir (v / r sabit): vZ / 15 = 10 / 50 -> vZ = 3 m/s.'),
  ('Üç adet özdeş dişli çark (K, L, M) merkezlerinden geçen millerle bir üçgen oluşturacak biçimde yerleştirilip her biri diğer ikisine dıştan dişleriyle kenetlenmeye çalışılıyor. Bu mekanizma çalıştırılmak istendiğinde ne gözlenir?', 'Dişliler birbirini kilitler ve sistem hiçbir yönde dönemez', ['Üç dişli de aynı açısal süratle saat yönünde serbestçe döner', 'Ortadaki dişli dururken diğer iki dişli zıt yönlerde döner', 'Tur sayıları yarıya düşerek mekanik avantaj üç katına çıkar'], 'Kapalı tek sayıda (3 adet) dıştan kenetli dişli halkasında K saat yönünde dönmek isterse L tersine, M tekrar saat yönüne dönmek ister; M ile K de temas halinde olduğundan ikisi aynı yönde dönemez ve sistem kilitlenir.'),
  ('Bir anahtarla sıkışmış bir somunu sökmeye çalışan tamirci, anahtarı tüm gücüyle itmesine rağmen somunu döndürememektedir. Tamirci anahtarın sapına uzun bir demir boru geçirip borunun ucundan aynı kuvvetle ittiğinde somunun kolayca açılmasının nedeni nedir?', 'Dönme eksenine olan dik uzaklığı (kuvvet kolunu) büyüterek somun üzerindeki torku artırması', ['Uyguladığı kuvvetin büyüklüğünü demir boru içinde rezonansla artırması', 'Somun ile cıvata dişleri arasındaki vida adımını iki katına çıkarması', 'Somunu açmak için gereken minimum mekanik işi yarı yarıya düşürmesi'], 'Boru eklemek kuvvet kolunu (R) uzatır; aynı F kuvvetiyle çok daha büyük bir döndürme momenti (tork = F·R) elde edilir.'),
  ('Yarıçapları 4r ve r olan eş merkezli K ve L kasnaklarından büyük olan K kasnağına sarılı ipin ucunda 60 N ağırlığında bir cisim asılıdır. Küçük olan L kasnağına sarılı ip ise ağırlıksız bir hareketli makaranın merkezine... değil, doğrudan Y cismine bağlı olup sistem dengededir. K ve L kasnaklarına ipler zıt yönlü tork oluşturacak biçimde sarıldığına göre L kasnağına asılı Y cisminin ağırlığı kaç N\'dur?', '240 N', ['15 N', '120 N', '180 N'], 'Merkeze göre tork dengesinden 60 · 4r = Y · r yazılır ve Y = 240 N bulunur.'),
  ('Aynı yüksekliğe sahip iki farklı vidadan birincisinin vida adımı 1 mm, ikincisinin vida adımı 2 mm\'dir. Özdeş iki tahta bloğa aynı uzunluktaki anahtarla tamamen vidalandıklarında (direnç kuvvetleri eşit ve sürtünme kayıpları önemsiz), iki durum için aşağıdakilerden hangisi doğrudur?', 'Birinci vidayı döndürmek için gereken kuvvet ikincinin yarısı kadardır, ancak birinci vida iki kat fazla tur döndürülür', ['Birinci vidayı tamamen gömmek için yapılan toplam iş, ikinci vidayı gömmek için yapılan işin yarısıdır', 'İkinci vidanın kuvvet kazancı birincinin iki katı olduğu için daha az kuvvetle vidalanır', 'Her iki vidanın da tamamen gömülmesi için eşit sayıda tam tur döndürülmeleri gerekir'], 'Direnç kuvveti R ve vidanın gömülme derinliği H aynı olduğundan toplam iş (R·H) eşittir; adımı 1 mm olan vida 2 kat fazla tur atar ve yarı kuvvet gerektirir.'),
  ('Bir inşaat vinci palangasında 400 kg kütleli çelik kiriş 10 saniyede sabit hızla 6 metre yüksekliğe çıkarılmaktadır. Vinç sisteminin mekanik verimi %80 olduğuna göre, vincin elektrik motorunun bu süreçte harcadığı giriş gücü kaç Watt\'tır? (g = 10 m/s^2)', '3000 Watt', ['2400 Watt', '1920 Watt', '3600 Watt'], 'Yararlı iş W_yararlı = m·g·h = 400·10·6 = 24000 Joule. Verim %80 olduğundan toplam harcanan enerji E_giriş = 24000 / 0,80 = 30000 Joule. Güç P = E / t = 30000 / 10 = 3000 Watt bulunur.'),
  ('Eşit kollu olmayan bir bahçe makasında (dal budama makası) tutma saplarının bıçak ağzına göre çok uzun tasarlanmasının nedeni aşağıdakilerden hangisidir?', 'Kuvvet kolunu yük koluna göre büyüterek kalın dalları az bir el kuvvetiyle kesebilmek', ['Parmakların küçük bir hareketiyle bıçak uçlarının çok geniş bir mesafe kat etmesini sağlamak', 'Desteği makasın en uç noktasına taşıyarak tek taraflı kaldıraç elde etmek', 'Dalın kesilmeye karşı gösterdiği direnç kuvvetini sürtünmeyle büyütmek'], 'Budama makasında sert dalları kesmek için yüksek kuvvet gerekir; bu yüzden saplar uzun (kuvvet kolu büyük), bıçaklar kısa (yük kolu küçük) yapılır.'),
  ('Sürtünmeli bir eğik düzlemin verimi %75\'tir. Eğik düzlemin yüksekliği 3 metre, uzunluğu 6 metre olduğuna göre, eğik düzlem üzerindeki 120 N ağırlığındaki bir cismi sabit hızla yukarı çeken paralel kuvvet kaç N\'dur ve yüzeydeki sürtünme kuvveti kaç N\'dur?', 'Çeken kuvvet 80 N, sürtünme kuvveti 20 N', ['Çeken kuvvet 60 N, sürtünme kuvveti 20 N', 'Çeken kuvvet 80 N, sürtünme kuvveti 40 N', 'Çeken kuvvet 90 N, sürtünme kuvveti 30 N'], 'Yararlı iş = 120·3 = 360 J. Verim %75 olduğundan toplam iş F·6 = 360 / 0,75 = 480 J -> F = 80 N. Ağırlığın paralel bileşeni 120·(3/6) = 60 N olduğundan sürtünme kuvveti fs = 80 - 60 = 20 N bulunur.'),
  ('Yarıçapı 10 cm olan bir dişli çark dakikada 120 devir (RPM) yapmaktadır. Bu dişliye dıştan kenetlenmiş 40 cm yarıçaplı ikinci dişlinin periyodu kaç saniyedir?', '2 saniye', ['0,5 saniye', '4 saniye', '1 saniye'], 'Birinci dişli 60 saniyede 120 devir yapıyorsa saniyede 2 devir yapar (f1 = 2 Hz). Yarıçapı 4 kat büyük olan ikinci dişlinin frekansı 4\'te biri olur: f2 = 2 / 4 = 0,5 Hz. Periyot T2 = 1 / f2 = 2 saniyedir.'),
  ('İç içe geçmiş (içten dişli / halka dişli) bir düzenekte dıştaki büyük halka dişli sabit olmayıp merkezi etrafında dönebilmektedir ve içten kendisine temas eden küçük pinyon dişliyi döndürmektedir. İçten temas eden bu iki dişlinin dönme yönleri ve çizgisel süratleri hakkında ne söylenebilir?', 'Dönme yönleri aynıdır ve temas noktasındaki çizgisel süratleri birbirine eşittir', ['Dönme yönleri zıttır ve açısal süratleri birbirine eşittir', 'Dönme yönleri aynıdır ve tur sayıları birbirine eşittir', 'Dönme yönleri zıttır ve temas noktasındaki çizgisel süratleri farklıdır'], 'Dıştan temasın aksine, içten temas eden dişli çarklar (veya aynı yönlü iç kasnaklar) aynı yönde dönerler ve temas ettikleri dişler üzerinde çizgisel süratleri eşittir.'),
  ('Eşit bölmeli, ağırlığı 20 N olan türdeş 6 bölmeli bir kaldıraç sol ucundan menteşelenmiştir. Ortasına (3. bölmeye) 80 N\'luk bir yük asılmış ve sağ ucundan (6. bölmeden) düşey yukarı uygulanan kuvvetle çubuk sabit hızla çok küçük bir miktar yükseltilmiştir. Çubuğun kendi ağırlığı amaç dışı yük sayıldığına göre bu kaldıracın yükü kaldırma verimi yüzde kaçtır?', '%80', ['%75', '%90', '%85'], 'Sol uca göre torktan F·6 = 80·3 + 20·3 = 300 -> F = 50 N. Sağ uç 2h yükseldiğinde orta nokta (hem yük hem de çubuğun kütle merkezi) h yükselir. Yararlı iş = 80·h, toplam iş = 50·2h = 100·h. Verim = (80h / 100h)·100 = %80 bulunur.'),
  ('Sürtünmeli bir basit makinede sadece uygulanan yükün ağırlığı artırıldığında (makinenin kendi hareketli parça ağırlığı varsa ve sürtünme sabit veya makara ağırlığı baskınsa; netleştirelim: sürtünmesiz fakat hareketli makara ağırlığı G olan bir palangada), kaldırılan P yükünün ağırlığı artırıldığında düzeneğin verimi nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Önce artar sonra sıfır olur'], 'Sürtünmesiz fakat makara ağırlıklı palangada verim = P / (P + G_hareketli) bağıntısıyla bulunur; P büyüdükçe bu kesir 1\'e (%100\'e) yaklaşır, yani verim artar.'),
  ('Sürtünmesiz bir eğik düzlemde 80 N ağırlığındaki bir cisim, eğik düzleme paralel bir ip yardımıyla tepedeki sabit makaradan geçirilerek ağırlıksız bir hareketli makaranın gövdesine üstten bağlanmıştır. Hareketli makaranın etrafından geçen diğer ipin bir ucu zemine sabitlenmiş, diğer ucunda ise aşağı doğru 15 N\'luk kuvvet uygulanarak denge sağlanmıştır. Eğik düzlemin kuvvet kazancı kaçtır?', '8 / 3', ['16 / 3', '4', '8 / 5'], 'Hareketli makarayı aşağı çeken iki paralel kol 15\'er N olduğundan üstteki ipin gerilmesi 2·15 = 30 N\'dur. Eğik düzlemdeki 80 N\'luk cismi 30 N dengelediğine göre kuvvet kazancı 80 / 30 = 8/3 bulunur.'),
  ('Yarıçapları 4r ve r olan eş merkezli K ve L kasnaklarından büyük olan K kasnağına sarılı ipin ucunda 60 N ağırlığında bir cisim asılıdır. Küçük olan L kasnağına zıt tork üretecek biçimde sarılı diğer ipin ucunda ise Y cismi asılı olup sistem dengededir. Buna göre Y cisminin ağırlığı kaç N\'dur?', '240 N', ['15 N', '120 N', '180 N'], 'Merkeze göre tork dengesinden 60 · 4r = Y · r yazılır ve Y = 240 N bulunur.'),
  ('Sürtünmelerin önemsiz olduğu fakat hareketli makara ağırlığının G olduğu bir palangada, yalnızca kaldırılan P yükünün ağırlığı artırıldığında düzeneğin mekanik verimi nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Önce artar sonra sıfır olur'], 'Sürtünmesiz fakat makara ağırlıklı palangada verim = P / (P + G_hareketli) bağıntısıyla bulunur; P büyüdükçe bu kesir 1\'e (%100\'e) yaklaşır, yani verim artar.'),
  ('Vida adımı 4 mm olan bir cıvata, sabit bir somun içerisinde dakikada 30 devir yapacak şekilde sabit açısal hızla döndürülmektedir. Cıvatanın ucunun somun içindeki ilerleme sürati kaç mm/s\'dir?', '2 mm/s', ['4 mm/s', '120 mm/s', '0,5 mm/s'], 'Dakikada (60 saniyede) 30 devir yapan cıvata 1 saniyede 0,5 devir yapar. Her devirde 4 mm ilerlediğine göre ilerleme sürati v = 0,5 · 4 = 2 mm/s\'dir.'),
  ('Bir öğrenci laboratuvarda kurduğu sürtünmeli bir basit makine düzeneğinde giriş kuvvetinin yaptığı işi 500 Joule, yükün kazandığı potansiyel enerjiyi ise 350 Joule olarak ölçüyor. Kaybolan 150 Joule enerji ile ilgili öğrencinin yapacağı hangi yorum bilimsel olarak doğrudur?', 'Enerji yok olmamış, sürtünmeli yüzeylerde ve ip-makara temas noktalarında ısı enerjisine dönüşmüştür', ['Basit makine yoldan kayıp yaşadığı için 150 Joule enerji uzay boşluğunda tamamen yok olmuştur', 'Kuvvet kazancı birden büyük olduğu için aradaki fark kuvvetin kendisine dönüşerek depolanmıştır', 'Ölçüm kesinlikle hatalıdır çünkü tüm basit makinelerde giriş işi ile çıkış işi birbirine eşittir'], 'Enerjinin korunumu yasası gereği enerji yok olmaz; aradaki 150 Joule fark sürtünmelerle ısı enerjisine dönüşmüştür.'),
  ('Yarıçapları r ve 2r olan K ve L kasnakları çapraz bir kayışla bağlanmış olup L kasnağı sabit ekseni etrafında dönerek kendisine eş merkezli r yarıçaplı tambura sarılı ipi çekmektedir. K kasnağı saat yönünde 4 tur döndürüldüğünde, tamburun sağ kenarından sarkan ipin ucundaki yük hangi yönde kaç pi·r hareket eder?', '4·pi·r kadar yükselir', ['4·pi·r kadar alçalır', '8·pi·r kadar yükselir', '8·pi·r kadar alçalır'], 'K kasnağı saat yönünde 4 tur dönerse çapraz bağlı L kasnağı (2r yarıçaplı) saat yönünün tersine 2 tur döner; sağ kenardan sarkan ip yukarı doğru sarılır ve yük 2 · (2·pi·r) = 4·pi·r yükselir.'),
  ('Bir palanga sisteminde kullanılan ipin çok hafif olması yerine oldukça ağır ve kalın bir demir zincir kullanılması durumunda düzeneğin verimi nasıl etkilenir?', 'Zincirin ağırlığını da yükseltmek için ek iş yapılacağından verim düşer', ['Zincir esnemediği için verim %100\'ün üzerine çıkar', 'Ağır zincir yükü kendi kendine çekeceği için giriş işi sıfırlanır', 'Verim yalnızca sabit makara yarıçapına bağlı olduğundan hiç değişmez'], 'Yük dışında yükseltilen her türlü ek ağırlık amaç dışı potansiyel enerji harcaması yaratarak verimi düşürür.'),
  ('Merkezleri sabit K, L ve M dişlilerinden K ile L dıştan temas etmekte, L ile M ise eş merkezli olarak birbirine perçinlenmiş bulunmaktadır. Diş sayıları sırasıyla zK = 30, zL = 10 ve zM = 40\'tır. K dişlisi dakikada 20 devir yaptığına göre M dişlisi dakikada kaç devir yapar?', '60 devir', ['15 devir', '20 devir', '80 devir'], 'K ile L dıştan kenetli olduğundan 20·30 = nL·10 -> nL = 60 devir/dakika bulunur. M dişlisi L ile eş merkezli olduğu için dakikada 60 devir yapar.'),
];
